  ('f4cfa86f-7d34-5ac6-86ba-12ccc351ffbd', 'AK', 'state', null, 'File a Consumer Complaint, Alaska Department of Law', 'https://www.law.alaska.gov/department/civil/consumer/cp_complaint.html', 'Alaska Department of Law, Consumer Protection Unit', 'state_attorney_general', 'complaint_filing', array['general']::text[], 'tenant', 'html', 'Online consumer complaint process of the Consumer Protection Unit, which mediates complaints about unfair or deceptive practices.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Lists Landlord & Tenant as a topic but does not explain how such complaints are handled."}'::jsonb),
  ('32aa739f-f60e-562e-a70c-7b4c2592539a', 'AK', 'state', null, 'Alaska Small Claims Handbook (SC-100)', 'https://public.courts.alaska.gov/web/forms/docs/sc-100.pdf', 'Alaska Court System', 'state_court', 'court_self_help', array['general','security_deposit']::text[], 'both', 'pdf', 'Court System handbook explaining how to file and respond to small claims cases of $10,000 or less.', null, null, 'unverifiable', 'Connection refused (ECONNREFUSED) and curl timed out. Indirect corroboration: the Alaska Department of Law landlord-tenant page links to this exact URL as ''Alaska Small Claims Handbook''. The $10,000 limit was not verified in-session.', '2026-10-19T00:00:00Z', '{"notes":"Court System hosts refused connections in this session. URL taken from the Department of Law landlord-tenant page."}'::jsonb),
  ('2c394b3e-d81a-5895-ae5d-cd3da4b96125', 'AK', 'state', null, 'Alaska State Commission for Human Rights', 'https://humanrights.alaska.gov/', 'Alaska State Commission for Human Rights', 'state_agency', 'fair_housing', array['fair_housing']::text[], 'tenant', 'html', 'State civil-rights agency that accepts complaints of housing discrimination, including online filing.', 'AS 18.80', null, 'unverifiable', 'AWS WAF captcha (''Human Verification'', HTTP 405, x-amzn-waf-action: captcha). WebSearch was not available and no official page linking to it was found, so the online housing-complaint filing claim is unverified.', '2026-10-19T00:00:00Z', '{"notes":"Returned HTTP 405 to automated fetch. URL and complaint role confirmed by the Department of Law 2024 handbook."}'::jsonb),
  ('60a2fd4f-6ca1-59e3-98d5-5ca6730c6f34', 'AK', 'state', null, 'Anchorage Equal Rights Commission', 'https://www.muni.org/departments/aerc/Pages/default.aspx', 'Municipality of Anchorage', 'local_government', 'fair_housing', array['fair_housing']::text[], 'tenant', 'html', 'Municipal agency that investigates discrimination complaints in Anchorage, including housing, with an intake questionnaire.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Local to Anchorage only."}'::jsonb),
  ('9f960140-dbd2-5d11-8695-3fef471a708f', 'AK', 'state', null, 'Report Housing Discrimination', 'https://www.hud.gov/reporthousingdiscrimination', 'U.S. Department of Housing and Urban Development', 'federal_agency', 'fair_housing', array['fair_housing']::text[], 'tenant', 'html', 'HUD page for filing a housing discrimination complaint under the federal Fair Housing Act.', null, null, 'unverifiable', 'hud.gov returns a Cloudflare 403 for all paths, and WebSearch was not available. Uncorroborated: other official pages still link to https://www.hud.gov/program_offices/fair_housing_equal_opp/online-complaint. Verify in a browser.', '2026-10-19T00:00:00Z', '{"notes":"hud.gov returned HTTP 403 to automated fetch; URL confirmed by search results."}'::jsonb),
  ('e1baf8b9-3434-5c0c-a3e2-b613f6bd5776', 'AK', 'state', null, 'Real Estate Disclosures about Potential Lead Hazards', 'https://www.epa.gov/lead/real-estate-disclosures-about-potential-lead-hazards', 'U.S. Environmental Protection Agency', 'federal_agency', 'health_safety', array['lead_mold_pests']::text[], 'both', 'html', 'EPA page explaining the federal lead-based paint disclosure rule for leasing and selling housing built before 1978.', '40 CFR Part 745, Subpart F', '2026-05-27', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Federal rule that applies in every state. The Alaska handbook also cites it."}'::jsonb),
  ('0b910a19-d78d-547d-be80-bca34a20c39b', 'AK', 'state', null, 'HUD: Alaska resources', 'https://www.hud.gov/states/alaska', 'U.S. Department of Housing and Urban Development', 'federal_agency', 'hud_state_page', array['general','eviction','rental_assistance','fair_housing']::text[], 'both', 'html', 'HUD''s Alaska page with rent relief and eviction resources, discrimination complaint links, housing-quality contacts and local HUD offices.', null, null, 'unverifiable', 'hud.gov blocks automated checks; URL follows the post-2025 redesign pattern confirmed via Internet Archive captures.', '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('35ce1687-7090-5e13-b263-34fd44d15352', 'AK', 'state', null, 'Alaska Law Help', 'https://alaskalawhelp.org', 'Alaska Legal Services Corporation and partners', 'legal_aid', 'legal_aid_directory', array['general','eviction']::text[], 'tenant', 'html', 'Statewide free legal information self-help website, including housing and landlord-tenant topics.', null, null, 'unverifiable', 'Cloudflare challenge (403, cf-mitigated: challenge). Indirect corroboration: the ALSC housing page links to https://alaskalawhelp.org as ''Alaska Law Help''. WebSearch was not available.', '2026-10-19T00:00:00Z', '{"notes":"Returned HTTP 403 to automated fetch. URL taken from the ALSC housing page and the Department of Law handbook."}'::jsonb),
  ('bfacc949-1cb6-5433-a61e-2c00e42999bf', 'AK', 'state', null, 'Housing, Alaska Legal Services Corporation', 'https://www.alsc-law.org/housing/', 'Alaska Legal Services Corporation', 'legal_aid', 'legal_aid_directory', array['general','eviction','repairs_habitability']::text[], 'tenant', 'html', 'Statewide legal aid provider''s housing page covering free help with landlord-tenant disputes, evictions and maintenance issues.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Links to Apply for Help and to AlaskaLawHelp.org."}'::jsonb),
  ('25e8c5e8-129b-51e9-abf1-ec9026a3c866', 'AK', 'state', null, 'Landlord and Tenant Helpline', 'https://www.alsc-law.org/helpline/', 'Alaska Legal Services Corporation', 'legal_aid', 'legal_aid_directory', array['general']::text[], 'both', 'html', 'Volunteer-attorney phone helpline answering housing questions from both tenants and landlords.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Hours per page: generally Mon-Thu, 6-8 p.m."}'::jsonb),
  ('234bb118-af3d-555d-a51c-7b19fba5db18', 'AK', 'state', null, 'Landlord and Tenant Information, Alaska Department of Law', 'https://law.alaska.gov/consumer/landlord-tenant.html', 'Alaska Department of Law, Consumer Protection Unit', 'state_attorney_general', 'official_guide', array['general']::text[], 'both', 'html', 'Department of Law page offering the state landlord-tenant handbook and links to the statute, small claims and legal help.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('b14b8796-48ac-5e37-8c35-44799d5713c7', 'AK', 'state', null, 'The Alaska Landlord & Tenant Act: What It Means to You (2024)', 'https://law.alaska.gov/pdf/consumer/LandlordTenant_web.pdf', 'Alaska Department of Law', 'state_attorney_general', 'official_guide', array['general','repairs_habitability','security_deposit','eviction','rent_increase','late_fees','retaliation','entry_privacy','lease_termination','fair_housing']::text[], 'both', 'pdf', 'State-approved handbook summarizing landlord and tenant rights and duties under AS 34.03, with sample notice forms for repairs, termination, rent increases and deposit offsets.', 'AS 34.03', '2024 edition', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Approved by the Alaska Department of Law under AS 44.23.020(b)(8). It advises checking for amendments when used after 2024."}'::jsonb),
  ('4fd6a7d0-522b-5a55-90ba-cd7edbf4f4b8', 'AK', 'state', null, 'Alaska Statutes Chapter 34.03: Uniform Residential Landlord and Tenant Act', 'https://www.akleg.gov/basis/statutes.asp#34.03', 'Alaska State Legislature', 'state_legislature', 'statute', array['general','repairs_habitability','security_deposit','eviction','retaliation','rent_increase']::text[], 'both', 'html', 'Official text of Alaska''s Uniform Residential Landlord and Tenant Act on the Legislature''s statutes site.', 'AS 34.03.010-34.03.380 (deposits .070; landlord maintenance .100; tenant remedies .160-.190; termination for tenant breach .220; periodic tenancy notice .290; retaliation .310)', null, 'unverifiable', 'akleg.gov returns a Cloudflare ''Sorry, you have been blocked'' page (403). Indirect corroboration: the official Alaska Department of Law landlord-tenant page links to this exact URL as ''Uniform Residential Landlord and Tenant Act''.', '2026-10-19T00:00:00Z', '{"notes":"akleg.gov returned HTTP 403 to automated fetch. The chapter URL is copied from the Alaska Department of Law''s landlord-tenant page. Section numbers come from the Department of Law''s 2024 handbook footnotes. Section-level anchors were not verified, so they are not listed separately."}'::jsonb),
  ('4754de39-4060-520e-b78d-11730027463f', 'AL', 'state', null, 'Consumer Complaint, Alabama Attorney General', 'https://www.alabamaag.gov/consumer-complaint/', 'Office of the Alabama Attorney General, Consumer Interest Division', 'state_attorney_general', 'complaint_filing', array['general']::text[], 'tenant', 'html', 'Online form for filing a consumer complaint with the Attorney General''s Consumer Interest Division, which mediates complaints.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The page does not name landlord-tenant disputes, but AG press releases found by search list landlord/tenant issues among top complaint categories."}'::jsonb),
  ('87ca99da-32ae-5e51-a455-95350b484796', 'AL', 'state', null, 'Answer to Landlord''s Claim - Residential Eviction/Unlawful Detainer (Form PS-01)', 'https://www.alabamalegalhelp.org/resource/answer-to-landlords-claim-residental-eviction', 'Alabama State Bar (hosted by Legal Services Alabama)', 'bar_association', 'court_self_help', array['eviction']::text[], 'tenant', 'html', 'Self-help answer form with instructions for tenants responding to a residential eviction (unlawful detainer) claim.', null, '2014-07-24 (last review)', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Alabama judicial websites (judicial.alabama.gov, alacourt.gov) refused connections in this session, so a statewide judiciary self-help page could not be opened."}'::jsonb),
  ('c59738fb-ad52-5f93-95a8-23f2aeb813d7', 'AL', 'state', null, 'Unlawful Detainers (Eviction), Montgomery County District Court', 'https://montgomery.alacourt.gov/district-civil/unlawful-detainers/', 'Alabama Unified Judicial System, Montgomery County District Court', 'state_court', 'court_self_help', array['eviction']::text[], 'landlord', 'html', 'County district court page describing how unlawful detainer (eviction) cases are filed, including Form C-59 and the required notice to tenant.', null, null, 'unverifiable', 'Connection refused (ECONNREFUSED) for WebFetch, and curl timed out on every alacourt.gov host (montgomery, eforms, www). This looks like network or geo blocking. WebSearch was not available, so the page''s existence, Form C-59 and the notice requirements are all unconfirmed. Verify manually.', '2026-10-19T00:00:00Z', '{"notes":"Connection refused during automated fetch; existence and content confirmed via search results. This is a county-level page, not a statewide one."}'::jsonb),
  ('bacdc775-0a1d-5fee-afad-6ed800b3bb68', 'AL', 'state', null, 'Writ of Restitution or Possession (AOC form C-59A)', 'https://eforms.alacourt.gov/media/b5mnsjxp/writ-of-restitution-or-possession.pdf', 'Alabama Administrative Office of Courts', 'state_court', 'court_self_help', array['eviction']::text[], 'landlord', 'pdf', 'Official statewide court form used to request a writ of possession after an eviction judgment.', null, null, 'unverifiable', 'Connection refused or timed out (the same alacourt.gov block as above). The form number C-59A and the title are unconfirmed, and WebSearch was not available. Verify manually.', '2026-10-19T00:00:00Z', '{"notes":"eforms.alacourt.gov refused connections in this session; URL confirmed by search results."}'::jsonb),
  ('cac642fb-7279-5c9c-9fcf-9862b50dcd02', 'AL', 'state', null, 'Fair Housing, AlabamaLegalHelp.org', 'https://www.alabamalegalhelp.org/issues/housing/fair-housing', 'Legal Services Alabama', 'legal_aid', 'fair_housing', array['fair_housing']::text[], 'tenant', 'html', 'Legal-aid page linking to HUD and DOJ fair housing information and HUD complaint options for Alabama residents.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"No state fair-housing agency complaint page was found; see gaps."}'::jsonb),
  ('71b513a8-d21b-5205-84db-3215b1f59745', 'AL', 'state', null, 'Report Housing Discrimination', 'https://www.hud.gov/reporthousingdiscrimination', 'U.S. Department of Housing and Urban Development', 'federal_agency', 'fair_housing', array['fair_housing']::text[], 'tenant', 'html', 'HUD page for filing a housing discrimination complaint under the federal Fair Housing Act.', null, null, 'unverifiable', 'hud.gov returns a Cloudflare 403 for all paths, and WebSearch was not available. Uncorroborated: other official pages still link to https://www.hud.gov/program_offices/fair_housing_equal_opp/online-complaint. Verify in a browser.', '2026-10-19T00:00:00Z', '{"notes":"hud.gov returned HTTP 403 to automated fetch; URL confirmed by search results."}'::jsonb),
  ('3c7e289f-70d2-541c-bd21-56c1309c7cd2', 'AL', 'state', null, 'The Fair Housing Act', 'https://www.justice.gov/crt/fair-housing-act-1', 'U.S. Department of Justice, Civil Rights Division', 'federal_agency', 'fair_housing', array['fair_housing']::text[], 'both', 'html', 'DOJ overview of the federal Fair Housing Act, its protected classes and how complaints go to HUD or federal court.', '42 U.S.C. 3601 et seq.', '2023-06-22', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('42387388-c744-5420-aebf-59e860747645', 'AL', 'state', null, 'Indoor Air Quality/Lead Branch', 'https://www.alabamapublichealth.gov/iaq/index.html', 'Alabama Department of Public Health', 'state_agency', 'health_safety', array['lead_mold_pests']::text[], 'both', 'html', 'State health department page on lead, indoor air quality and mold, with referrals for renters to landlord-tenant fact sheets.', null, '2025-10-30', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Its linked ''Landlord-Tenant Law Fact Sheet'' is a 2006 Arise fact sheet with outdated deposit deadlines, so it is not listed here."}'::jsonb),
  ('ca9df20c-5e6f-5cd2-8974-1620e3e4bc46', 'AL', 'state', null, 'Real Estate Disclosures about Potential Lead Hazards', 'https://www.epa.gov/lead/real-estate-disclosures-about-potential-lead-hazards', 'U.S. Environmental Protection Agency', 'federal_agency', 'health_safety', array['lead_mold_pests']::text[], 'both', 'html', 'EPA page explaining the federal lead-based paint disclosure rule for leasing and selling housing built before 1978.', '40 CFR Part 745, Subpart F', '2026-05-27', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Federal rule that applies in every state."}'::jsonb),
  ('08b52134-c08f-5745-84c3-d751e33bdfde', 'AL', 'state', null, 'HUD: Alabama resources', 'https://www.hud.gov/states/alabama', 'U.S. Department of Housing and Urban Development', 'federal_agency', 'hud_state_page', array['general','eviction','rental_assistance','fair_housing']::text[], 'both', 'html', 'HUD''s Alabama page with rent relief and eviction resources, discrimination complaint links, housing-quality contacts and local HUD offices.', null, null, 'unverifiable', 'hud.gov blocks automated checks; URL follows the post-2025 redesign pattern confirmed via Internet Archive captures.', '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('15607307-916e-598f-8d5b-94e5e80e83eb', 'AL', 'state', null, 'Eviction, AlabamaLegalHelp.org', 'https://www.alabamalegalhelp.org/issues/housing/eviction', 'Legal Services Alabama', 'legal_aid', 'legal_aid_directory', array['eviction']::text[], 'tenant', 'html', 'Statewide legal-aid page collecting eviction information and do-it-yourself eviction answer forms for Alabama.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('8a93ef4c-a8c4-5a4d-acea-2e47b08a17f8', 'AL', 'state', null, 'Landlord and Tenant (Housing), AlabamaLegalHelp.org', 'https://www.alabamalegalhelp.org/issues/housing/landlord-and-tenant', 'Legal Services Alabama', 'legal_aid', 'legal_aid_directory', array['general','repairs_habitability','lease_termination','eviction']::text[], 'tenant', 'html', 'Statewide LawHelp-network collection of landlord-tenant information, including leases, repairs, lease termination and the Alabama Tenants'' Handbook.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Legal Services Alabama runs the site as an LSC-funded project with Pro Bono Net. Individual resources carry their own review dates."}'::jsonb),
  ('48c03f86-b48d-57fe-8d57-747a0da2bf63', 'AL', 'state', null, 'The Alabama Tenants'' Handbook (Revised 2024)', 'https://alarise.org/wp-content/uploads/2024/06/Alabama-Tenants-Handbook-2024-Update.pdf', 'Alabama Arise and Montgomery Volunteer Lawyers Program (editorial team includes the Alabama State Bar Volunteer Lawyers Program)', 'nonprofit', 'official_guide', array['general','repairs_habitability','security_deposit','eviction']::text[], 'tenant', 'pdf', 'Tenant handbook explaining rights and responsibilities under the Alabama Uniform Residential Landlord and Tenant Act.', null, 'Revised 2024', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Not a government publication; no Attorney General or agency landlord-tenant handbook was found for Alabama. AlabamaLegalHelp.org (Legal Services Alabama) links to it as the current version. Front matter confirmed via PDF text extraction."}'::jsonb),
  ('6f3cb7e0-5222-5e44-821c-a0bea09b78f1', 'AL', 'state', null, 'Repairs in Rental Housing', 'https://www.alabamalegalhelp.org/resource/repairs-in-rental-housing', 'Legal Services Alabama', 'legal_aid', 'other', array['repairs_habitability']::text[], 'tenant', 'html', 'Legal-aid explainer on landlord repair duties and the written-notice process for repair problems in Alabama rentals.', null, '2010-05-06 (last review)', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Last reviewed in 2010, so check it against the current statute."}'::jsonb),
  ('c92ab7b7-0343-5e95-ad5e-ae3f087a9607', 'AL', 'state', null, 'Ala. Code § 11-80-8.1: Ordinances controlling rent charged for leasing private property prohibited', 'https://law.justia.com/codes/alabama/title-11/title-3/chapter-80/section-11-80-8-1/', 'Justia (reprint of Code of Alabama)', 'other', 'rent_regulation', array['rent_control','rent_increase']::text[], 'both', 'html', 'Statute section prohibiting counties and municipalities from enacting or enforcing local rent control.', 'Ala. Code § 11-80-8.1', '2024 Code of Alabama', 'unverifiable', 'Justia returns 403, and WebSearch was not available. Official ALISON text confirms ''Section 11-80-8.1 Enactment of Ordinances, Resolutions, Etc., Controlling Rent Charged for Leasing Private Property Prohibited''. Its only history entry is Acts 1993, No. 93-421, so there were no 2024-2026 changes. The Justia path is unverified.', '2026-10-19T00:00:00Z', '{"notes":"Justia fallback (HTTP 403 to automated fetch). URL and title confirmed by search results."}'::jsonb),
  ('b776302c-87b8-58ce-ae35-117bd6302df0', 'AL', 'state', null, 'Ala. Code § 35-9A-201: Security deposits; prepaid rent', 'https://law.justia.com/codes/alabama/title-35/chapter-9a/article-2/section-35-9a-201/', 'Justia (reprint of Code of Alabama)', 'other', 'statute', array['security_deposit']::text[], 'both', 'html', 'Statute section on security deposit limits, refunds, itemized deductions and forfeiture of unclaimed deposits.', 'Ala. Code § 35-9A-201', '2025 Code of Alabama', 'unverifiable', 'Justia returns 403, and WebSearch was not available. Official ALISON text confirms ''Section 35-9A-201 Security Deposits; Prepaid Rent'': a one-month limit with exceptions, 60-day itemized refund, double-deposit penalty, and forfeiture of unclaimed deposits after 90 days (last amended by Act 2014-279). The Justia path is unverified.', '2026-10-19T00:00:00Z', '{"notes":"Justia fallback (HTTP 403 to automated fetch). URL confirmed by search results."}'::jsonb),
  ('ba0c5135-4995-58f0-870d-55d836033fb5', 'AL', 'state', null, 'Ala. Code § 35-9A-204: Landlord to maintain premises', 'https://law.justia.com/codes/alabama/title-35/chapter-9a/article-2/section-35-9a-204/', 'Justia (reprint of Code of Alabama)', 'other', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute section on the landlord''s duties to comply with health and safety codes, make repairs and keep the premises in a fit and habitable condition.', 'Ala. Code § 35-9A-204', '2025 Code of Alabama', 'unverifiable', 'Justia returns 403, and WebSearch was not available. Official ALISON text confirms ''Section 35-9A-204 Landlord to Maintain Premises'' (Act 2006-316), covering codes, repairs, habitable condition and common areas, so the title and description are accurate. The Justia path itself is unverified.', '2026-10-19T00:00:00Z', '{"notes":"Justia fallback (HTTP 403 to automated fetch). URL and section title confirmed by search results."}'::jsonb),
  ('3954b6a8-8c6e-5e56-ae74-9071ca94c747', 'AL', 'state', null, 'Ala. Code § 35-9A-401: Noncompliance by the landlord', 'https://law.justia.com/codes/alabama/title-35/chapter-9a/article-4/division-1/section-35-9a-401/', 'Justia (reprint of Code of Alabama)', 'other', 'statute', array['repairs_habitability','lease_termination']::text[], 'both', 'html', 'Statute section on tenant remedies when a landlord materially breaches the rental agreement or § 35-9A-204, including written notice, termination and damages.', 'Ala. Code § 35-9A-401', '2025 Code of Alabama', 'unverifiable', 'Justia returns 403, and WebSearch was not available. Official ALISON text confirms ''Section 35-9A-401 Noncompliance by the Landlord'': written notice, termination no sooner than 14 days after notice, and damages (Acts 2006-316, 2011-700). The Justia path is unverified.', '2026-10-19T00:00:00Z', '{"notes":"Justia fallback (HTTP 403 to automated fetch). URL confirmed by search results."}'::jsonb),
  ('654a98d7-795d-5aca-961d-a90c2423c5b9', 'AL', 'state', null, 'Ala. Code § 35-9A-461: Landlord''s action for eviction, rent, monetary damages, or other relief', 'https://law.justia.com/codes/alabama/title-35/chapter-9a/article-4/division-4/section-35-9a-461/', 'Justia (reprint of Code of Alabama)', 'other', 'statute', array['eviction']::text[], 'both', 'html', 'Statute section on the court procedure for eviction actions, including service, answers, appeals and writs of possession.', 'Ala. Code § 35-9A-461', '2025 Code of Alabama', 'unverifiable', 'Justia returns 403, and WebSearch was not available. Official ALISON text confirms ''Section 35-9A-461 Landlord''s Action for Eviction, Rent, Monetary Damages, or Other Relief'': service by posting, a 7-day appeal window, etc. (Act 2009-633). The Justia path, including ''division-4'', is unverified.', '2026-10-19T00:00:00Z', '{"notes":"Justia fallback (HTTP 403 to automated fetch). URL confirmed by search results. Pre-filing notice periods are in § 35-9A-421 (Division 2, Landlord Remedies), whose URL was not confirmed."}'::jsonb),
