  ('08d6d266-6e91-5382-9d5b-72199981ff28', 'CA', 'city', 'Sacramento, CA', 'Tenant Protection Program (Sacramento)', 'https://www.cityofsacramento.gov/community-development/code-compliance/rental-info-hub/tenant-protection-program', 'City of Sacramento Community Development - Code Compliance', 'local_government', 'rent_regulation', array['rent_increase','eviction']::text[], 'both', 'html', 'City page on the Tenant Protection and Relief Act program, which caps annual rent increases for covered units, protects against unwarranted lease termination and requires annual registration with a per-unit fee.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Sacramento has no rent board, but this local rent-cap program functions as rent regulation. The cap is updated every July 1 (8.6% from 2026-07-01). Link to it rather than copying the figure."}'::jsonb),
