  ('1af4dbd7-4bb8-56de-bd81-5eaef4f7d3bd', 'CA', 'state', null, 'Civil Code § 1941.1 - Untenantable dwelling (habitability standards)', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1941.1', 'California Legislative Information', 'state_legislature', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute listing the conditions that make a dwelling untenantable for purposes of the landlord''s repair duty.', 'Cal. Civ. Code § 1941.1', null, 'unverifiable', 'leginfo returns 403. Corroborated: selfhelp.courts.ca.gov links this exact URL, and the AG Habitability flyer cites § 1941.1 for habitability standards.', '2026-10-19T00:00:00Z', '{"notes":"Linked from oag.ca.gov/tenants. leginfo blocks automated fetching (HTTP 403)."}'::jsonb),
  ('80ae760b-737b-5f1f-9449-f5ce7c1f3604', 'CA', 'state', null, 'Civil Code § 1942 - Tenant repair and deduct', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=1942.&lawCode=CIV', 'California Legislative Information', 'state_legislature', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute on a tenant''s repair-and-deduct and vacate remedies when a landlord does not make required repairs after notice.', 'Cal. Civ. Code § 1942', null, 'unverifiable', 'leginfo returns 403. Corroborated: the Courts Eviction Defenses page links this exact URL under the repair-and-deduct defense.', '2026-10-19T00:00:00Z', '{"notes":"Confirmed in search results. leginfo returns HTTP 403 to automated requests."}'::jsonb),
  ('90022b79-3644-5020-894f-c4331345ace1', 'CA', 'state', null, 'Civil Code § 1942.4 - Rent demands for cited substandard dwellings', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1942.4.', 'California Legislative Information', 'state_legislature', 'statute', array['repairs_habitability','rent_increase']::text[], 'both', 'html', 'Statute limiting a landlord''s ability to demand or raise rent on a dwelling that a public officer has cited for uncorrected substandard conditions.', 'Cal. Civ. Code § 1942.4', null, 'unverifiable', 'leginfo returns 403. Corroborated: a CA official page links § 1942.4 as ...sectionNum=1942.4.&nodeTreePath=8.4.69.3&lawCode=CIV, which has the same section parameters.', '2026-10-19T00:00:00Z', '{"notes":"Confirmed in search results and linked from the Attorney General''s tenant page. leginfo returns HTTP 403."}'::jsonb),
  ('5300f411-eca6-5770-a481-eaf607f69f39', 'CA', 'state', null, 'Civil Code § 1942.5 - Retaliation', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1942.5', 'California Legislative Information', 'state_legislature', 'statute', array['retaliation']::text[], 'both', 'html', 'Statute prohibiting landlord retaliation against tenants who exercise their legal rights.', 'Cal. Civ. Code § 1942.5', null, 'unverifiable', 'leginfo returns 403. Corroborated: CA Courts self-help links this exact URL for the retaliation defense.', '2026-10-19T00:00:00Z', '{"notes":"Linked from oag.ca.gov/tenants. leginfo returns HTTP 403."}'::jsonb),
  ('df864850-9039-5035-b282-88869c6e06e2', 'CA', 'state', null, 'Civil Code § 1946.2 - Just cause for termination (Tenant Protection Act)', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1946.2', 'California Legislative Information', 'state_legislature', 'statute', array['eviction','lease_termination']::text[], 'both', 'html', 'Tenant Protection Act section that requires just cause to terminate covered tenancies.', 'Cal. Civ. Code § 1946.2', null, 'unverifiable', 'leginfo returns 403. Corroborated: CA official pages link this exact URL for the TPA just-cause rule.', '2026-10-19T00:00:00Z', '{"notes":"Linked from oag.ca.gov/tenants. leginfo returns HTTP 403."}'::jsonb),
  ('cd6f9e60-b49a-5c2d-99fb-abf6bdb7e126', 'CA', 'state', null, 'Civil Code § 1947.12 - Statewide rent cap (Tenant Protection Act)', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=1947.12.&lawCode=CIV', 'California Legislative Information', 'state_legislature', 'statute', array['rent_increase','rent_control']::text[], 'both', 'html', 'Tenant Protection Act section setting the statewide annual limit on rent increases for covered units.', 'Cal. Civ. Code § 1947.12', null, 'unverifiable', 'leginfo returns 403. Corroborated: oag.ca.gov/rentcaps links this exact URL twice. Its link text mistypes the section as ''1974.12''. The DRE 2026 guide confirms the section expires January 1, 2030 unless extended.', '2026-10-19T00:00:00Z', '{"notes":"Linked from oag.ca.gov/rentcaps. leginfo returns HTTP 403."}'::jsonb),
  ('fdc3a9ff-d4f8-597b-bb9f-51925e009370', 'CA', 'state', null, 'Civil Code § 1950.5 - Security deposits', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=1950.5&lawCode=CIV', 'California Legislative Information', 'state_legislature', 'statute', array['security_deposit']::text[], 'both', 'html', 'Statute on residential security deposit limits, permitted deductions, itemization and return.', 'Cal. Civ. Code § 1950.5', null, 'unverifiable', 'leginfo returns 403. Corroborated: CA Courts self-help links ...lawCode=CIV&sectionNum=1950.5, the same parameters in a different order. The AG deposit flyer cites § 1950.5.', '2026-10-19T00:00:00Z', '{"notes":"Confirmed in search results. Amended by AB 12 (one-month cap from July 1, 2024) and AB 2801 (photo documentation). leginfo returns HTTP 403."}'::jsonb),
  ('e02e7a07-8b3b-51ea-ae3e-4e2f7cde657c', 'CA', 'state', null, 'Civil Code § 827 - Notice of rent increase', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=827', 'California Legislative Information', 'state_legislature', 'statute', array['rent_increase']::text[], 'both', 'html', 'Statute on the written notice periods required before rent increases in periodic residential tenancies.', 'Cal. Civ. Code § 827', null, 'unverifiable', 'leginfo returns 403. Corroborated: CA official pages link this exact URL.', '2026-10-19T00:00:00Z', '{"notes":"Linked from oag.ca.gov/tenants. leginfo returns HTTP 403."}'::jsonb),
  ('274f2341-1d14-527d-9334-5ebc905c9318', 'CA', 'state', null, 'Code of Civil Procedure §§ 1159-1179a - Summary proceedings for possession (unlawful detainer)', 'https://leginfo.legislature.ca.gov/faces/codes_displayText.xhtml?chapter=4.&part=3.&lawCode=CCP&title=3.', 'California Legislative Information', 'state_legislature', 'statute', array['eviction']::text[], 'both', 'html', 'Official text of the Code of Civil Procedure chapter that governs unlawful detainer (eviction) proceedings.', 'Cal. Code Civ. Proc. §§ 1159-1179a', null, 'unverifiable', 'leginfo returns 403. Unverified. The URL follows the standard pattern for CCP Part 3, Title 3, Ch. 4 (Summary Proceedings for Obtaining Possession, §§ 1159-1179a). Courts pages link individual sections such as 1161 and 1174.2 using nodeTreePath=6.3.4, which is consistent with that chapter.', '2026-10-19T00:00:00Z', '{"notes":"Confirmed in search results. leginfo returns HTTP 403."}'::jsonb),
  ('b2f779b8-e884-5b39-9e31-163fa4703142', 'CA', 'county', 'Los Angeles County, CA', 'Los Angeles County Code Chapter 8.52 - Rent Stabilization and Tenant Protections', 'https://library.municode.com/ca/los_angeles_county/codes/code_of_ordinances?nodeId=TIT8COPRBUWARE_DIV3HO_CH8.52RESTTEPR', 'County of Los Angeles (via Municode)', 'local_government', 'statute', array['rent_control','rent_increase','eviction']::text[], 'both', 'html', 'Full text of the county''s Rent Stabilization and Tenant Protections Ordinance for unincorporated Los Angeles County.', 'Los Angeles County Code ch. 8.52', null, 'unverifiable', 'Municode serves a Cloudflare challenge (403, ''Just a moment...''), so I could not read the page. The URL is confirmed: the official DCBA pages (dcba.lacounty.gov/rentstabilizationprogram/ and /rentregistry/) link to this exact URL for Ch. 8.52.', '2026-10-19T00:00:00Z', '{"notes":"Link taken from the DCBA program page I opened. I did not open it myself because Municode renders with JavaScript."}'::jsonb),
  ('006d739a-6854-55a8-8df6-66ead8a85d2a', 'CA', 'city', 'San Diego, CA', 'San Diego Municipal Code Ch. 9, Art. 8, Div. 7 - Residential Tenant Protections', 'https://docs.sandiego.gov/municode/MuniCodeChapter09/Ch09Art08Division07.pdf', 'City of San Diego (Office of the City Clerk)', 'local_government', 'statute', array['eviction','lease_termination']::text[], 'both', 'pdf', 'Text of the City of San Diego''s Residential Tenant Protections division, which requires just cause for ending residential tenancies.', 'San Diego Municipal Code § 98.0701 et seq.', '2024-03', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Retitled by Ordinance O-21647, effective 2023-06-24. I found it through the official municipal code Chapter 9 index and extracted its text."}'::jsonb),
  ('c2c606cb-d040-561b-937e-e35e92e9bc38', 'CO', 'city', 'Denver, CO', 'Residential Health', 'https://www.denvergov.org/Government/Agencies-Departments-Offices/Agencies-Departments-Offices-Directory/Public-Health-Environment/Public-Health-Investigations/Healthy-Families-Healthy-Homes/Residential-Health', 'City and County of Denver – Department of Public Health & Environment (DDPHE)', 'local_government', 'code_enforcement', array['repairs_habitability','lead_mold_pests','utilities']::text[], 'both', 'html', 'DDPHE page on Denver''s minimum residential housing standards (plumbing, heat, utilities, sanitation, pests), the governing Residential Health rules and Housing Code, and public complaint and violation dashboards.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Page says investigations are complaint-based but does not itself name the intake channel; the site header points to 3-1-1 / ''Report an Issue'' (news reports confirm 311 routes housing complaints to DDPHE)."}'::jsonb),
  ('a76d01a4-4564-59fa-bf9d-7554354ce30b', 'CO', 'state', null, 'File a Complaint - Colorado Attorney General', 'https://coag.gov/file-complaint/', 'Colorado Department of Law, Office of the Attorney General', 'state_attorney_general', 'complaint_filing', array['repairs_habitability','fair_housing']::text[], 'tenant', 'html', 'Attorney General complaint hub, which includes a category for housing, rentals and mobile homes (discrimination, habitability, safety).', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Housing category portal: https://complaints.coag.gov/s/?varCFT=8 (HTTP 200, script-rendered form)."}'::jsonb)
