  ('f677c7f6-4708-5d61-9c8a-17944b7240ea', 'HI', 'state', null, '2024 Landlord-Tenant Handbook', 'https://cca.hawaii.gov/ocp/files/2024/12/2024-Landlord-Tenant-Handbook-Final.pdf', 'Hawaii Department of Commerce and Consumer Affairs, Office of Consumer Protection', 'state_agency', 'official_guide', array['general','repairs_habitability','security_deposit','rent_increase','late_fees','eviction','entry_privacy']::text[], 'both', 'pdf', 'The Office of Consumer Protection''s handbook summarizing Hawaii''s Residential Landlord-Tenant Code for landlords and tenants.', null, '2024 edition (file posted December 2024)', 'unverifiable', 'Cloudflare 403 to both WebFetch and curl, and WebSearch was unavailable, so the edition and contents are unconfirmed. Caution: a Dec. 2024 handbook predates Act 278 (L 2025, c 278), which from Feb. 5, 2026 replaced the 5-business-day nonpayment notice with a 10-day notice plus pre-filing mediation. Its eviction section is therefore likely out of date. Check the OCP page for a newer edition.', '2026-10-19T00:00:00Z', '{"notes":"Returned 403 to automated fetching. The URL and 2024 edition are confirmed by search results."}'::jsonb),
  ('a4ac9669-6fc1-5a2f-8157-3522b4f8c667', 'HI', 'state', null, 'Landlord Tenant (Office of Consumer Protection)', 'https://cca.hawaii.gov/ocp/landlord-tenant', 'Hawaii Department of Commerce and Consumer Affairs, Office of Consumer Protection', 'state_agency', 'official_guide', array['general','repairs_habitability','security_deposit','eviction','rent_increase']::text[], 'both', 'html', 'Office of Consumer Protection landlord-tenant page linking the state handbook, HRS chapter 521, the Landlord-Tenant Information Center and Maui wildfire rental FAQs.', null, null, 'unverifiable', 'Cloudflare 403 (''Just a moment...'') to both WebFetch and curl, and WebSearch was unavailable. Corroboration: the Hawaii Judiciary''s Act 278 page links to https://cca.hawaii.gov/ocp/landlord-tenant/ (trailing slash), so the page exists. Its listed contents (handbook, HRS 521, LTIC, Maui FAQs) are unverified.', '2026-10-19T00:00:00Z', '{"notes":"cca.hawaii.gov returned 403 to automated fetching. The URL is confirmed by search results, which describe the page as updated 10/8/24."}'::jsonb),
  ('ca1ed4ac-3047-538d-ad8d-af54155d5891', 'HI', 'state', null, '§ 127A-30 Rental or sale of essential commodities during a state of emergency; prohibition against price increases', 'https://data.capitol.hawaii.gov/hrscurrent/Vol03_Ch0121-0200D/HRS0127A/HRS_0127A-0030.htm', 'Hawaii State Legislature', 'state_legislature', 'rent_regulation', array['rent_control','rent_increase','eviction']::text[], 'both', 'html', 'Statute that, when invoked during a declared emergency, bars residential rent increases and limits tenancy terminations in the affected area.', 'Haw. Rev. Stat. § 127A-30', 'Amended L 2024, c 206', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('fd9b195c-8b3f-5c7f-8d05-21f5508557fc', 'HI', 'state', null, 'Thirty-Third Proclamation Relating to Wildfires (Oct. 16, 2026)', 'https://dod.hawaii.gov/hiema/files/2026/10/2610025_THIRTY-THIRD-PROCLAMATION-RELATING-TO-WILDFIRES.pdf', 'Office of the Governor, State of Hawaii (hosted by Hawaii Emergency Management Agency)', 'state_agency', 'rent_regulation', array['rent_control','rent_increase']::text[], 'both', 'pdf', 'Governor''s emergency proclamation that keeps the HRS § 127A-30 prohibition on residential rent increases on Maui at Aug. 9, 2023 levels.', null, 'Relief period through Oct. 23, 2026', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Replaced outdated link | Text extracted locally. It expires Oct. 23, 2026 unless extended or superseded, so check for a 33rd proclamation."}'::jsonb),
