  ('34bd7bdc-e24c-59d5-aebc-cb7377f294f4', 'HI', 'state', null, '§ 521-42 Landlord to supply and maintain fit premises', 'https://data.capitol.hawaii.gov/hrscurrent/Vol12_Ch0501-0588/HRS0521/HRS_0521-0042.htm', 'Hawaii State Legislature', 'state_legislature', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute on the landlord''s duty to comply with health and safety codes, make repairs and keep premises habitable, and prepare a move-in inventory.', 'Haw. Rev. Stat. § 521-42', 'Amended L 1989, c 143', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
