  ('3bc6e5c6-a467-5ca5-bf76-6e4827ae4482', 'HI', 'state', null, '§ 521-64 Tenant''s remedy of repair and deduction for minor defects', 'https://data.capitol.hawaii.gov/hrscurrent/Vol12_Ch0501-0588/HRS0521/HRS_0521-0064.htm', 'Hawaii State Legislature', 'state_legislature', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute on when a tenant may repair defects and deduct the cost from rent, with notice periods and dollar limits.', 'Haw. Rev. Stat. § 521-64', 'Amended L 2024, c 32', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('6d2389ff-b842-5614-89d0-eedf07c4420c', 'HI', 'state', null, '§ 521-68 Landlord''s remedies for failure by tenant to pay rent; prelitigation mediation', 'https://data.capitol.hawaii.gov/hrscurrent/Vol12_Ch0501-0588/HRS0521/HRS_0521-0068.htm', 'Hawaii State Legislature', 'state_legislature', 'statute', array['eviction']::text[], 'both', 'html', 'Statute on the written notice and pre-litigation mediation steps required before a landlord files for possession for unpaid rent.', 'Haw. Rev. Stat. § 521-68', 'Amended L 2025, c 278 (version effective Feb. 5, 2026)', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Act 278 (2025) changed the notice from 5 business days to 10 calendar days and added mediation-center notice. Parts are scheduled for repeal and reenactment on Feb. 4, 2028."}'::jsonb),
  ('6e936a77-a7bc-550a-884c-a739c975f3cf', 'HI', 'state', null, '§ 521-74 Retaliatory evictions and rent increases prohibited', 'https://data.capitol.hawaii.gov/hrscurrent/Vol12_Ch0501-0588/HRS0521/HRS_0521-0074.htm', 'Hawaii State Legislature', 'state_legislature', 'statute', array['retaliation','rent_increase','eviction']::text[], 'both', 'html', 'Statute prohibiting retaliatory eviction, rent increases or service reductions after code complaints or repair requests, and listing exceptions.', 'Haw. Rev. Stat. § 521-74', null, 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
