  ('ed07506b-866e-5c4a-8bf9-00a569189551', 'IA', 'state', null, 'Small Claims (Iowa Judicial Branch)', 'https://www.iowacourts.gov/for-the-public/representing-yourself/small-claims/', 'Iowa Judicial Branch', 'state_court', 'court_self_help', array['eviction','security_deposit']::text[], 'both', 'html', 'Iowa Judicial Branch self-help page on small claims cases, which notes that forcible entry and detainer (eviction) actions can be brought in small claims court.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"No eviction-specific self-help page or form set was found on iowacourts.gov."}'::jsonb),
  ('02ffd22f-433c-5ed5-a15e-a0e72a415ad4', 'IA', 'state', null, 'Housing Complaint Process (Iowa Office of Civil Rights)', 'https://icrc.iowa.gov/file-complaint/housing-complaint-process', 'Iowa Office of Civil Rights (Iowa Civil Rights Commission)', 'state_agency', 'fair_housing', array['fair_housing']::text[], 'both', 'html', 'State civil rights office page explaining how to file a housing discrimination complaint, including intake, investigation and mediation.', null, '2025-06-30', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Page states complaints must be filed within 300 days. The Commission has been housed in the Iowa Office of Civil Rights since 2024-07-01."}'::jsonb),
