  ('64e0d0cc-c2b2-58ca-8058-bcb8e597ffe8', 'IA', 'state', null, 'The Handbook for Older Iowans: Chapter 9, Landlord/Tenant', 'https://s3.amazonaws.com/membercentralcdn/sitedocuments/isba/isba/0879/3166879.pdf', 'The Iowa State Bar Association, Elder Law Section', 'bar_association', 'official_guide', array['general','security_deposit','repairs_habitability','rent_increase','retaliation','entry_privacy','lease_termination','eviction','rental_assistance']::text[], 'tenant', 'pdf', 'A bar-association handbook of general legal information for older Iowans. Its Landlord/Tenant chapter covers rental agreements, prohibited lease terms, rental deposits, landlord and tenant duties, rent increases, retaliation, landlord entry, ending a tenancy, eviction, and mobile home parks.', null, '2023 (7th edition)', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Opened and text-extracted the printer-friendly edition. The iowabar.org docDownload link redirects to a time-limited signed S3 PDF, so store the iowabar.org URL, not the S3 one. The full-color edition is https://www.iowabar.org/docDownload/2163346; it redirected but was too large to open (over 10 MB). Both are listed on https://www.iowabar.org/?pg=GuidesandHandbooks. There is also a ''Property Tax and Rent Relief'' chapter. The chapter starts on handbook page 35 in the printed TOC."}'::jsonb),
  ('610911e4-1364-5c63-99ac-74ad5fe4f349', 'IA', 'state', null, 'Home & Property (Iowa Attorney General)', 'https://www.iowaattorneygeneral.gov/for-consumers/general-consumer-information/home-property/', 'Iowa Attorney General, Consumer Protection Division', 'state_attorney_general', 'other', array['general']::text[], 'both', 'html', 'Attorney General consumer page on home and property issues, including fake rental listings and where to refer landlord-tenant disputes.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Page states the Consumer Protection Division generally does not resolve ordinary landlord-tenant disputes or handle security deposit or lease disputes."}'::jsonb),
