  ('232063fc-ee34-5cc6-8f24-3d5fd0506395', 'IA', 'state', null, 'Landlord and Tenant Law Questions and Answers (Iowa Legal Aid)', 'https://iowalegalaid.org/resource/landlord-and-tenant-law-questions-and-answers/', 'Iowa Legal Aid', 'legal_aid', 'other', array['general','security_deposit','repairs_habitability','rent_increase','entry_privacy','eviction']::text[], 'tenant', 'html', 'Legal aid Q&A on common Iowa landlord-tenant questions, including deposits, repairs, rent increases, landlord entry and eviction.', null, '2025-10-30', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb)
