  ('b31472e7-652e-5b7c-965b-679af06bce09', 'ID', 'state', null, 'Idaho Code 55-304 - Change in lease terms and notice', 'https://legislature.idaho.gov/statutesrules/idstat/title55/t55ch3/sect55-304/', 'Idaho Legislature', 'state_legislature', 'statute', array['rent_increase','lease_termination']::text[], 'both', 'html', 'Official text of Idaho Code 55-304 on the written notice required to change lease terms, including notice before a residential rent increase or lease nonrenewal.', 'Idaho Code 55-304', null, 'unverifiable', 'legislature.idaho.gov refused the connection. A site-restricted search returned this exact URL as ''Section 55-304''. Its snippet confirms: month-to-month term changes need written notice at least 15 days before month end, and residential leases need 30 days'' written notice before a rent increase or nonrenewal. The July 2026 AG manual appendix lists 55-304 as ''Change in lease terms and notice''.', '2026-10-19T00:00:00Z', '{"notes":"Official site refused automated connection; URL confirmed via web search."}'::jsonb),
  ('385c787a-5fc4-5be7-806c-d684061b7b13', 'ID', 'state', null, 'Idaho Code 55-305 - Limitation on fees for tenants of a rental property', 'https://legislature.idaho.gov/statutesrules/idstat/Title55/T55CH3/SECT55-305/', 'Idaho Legislature', 'state_legislature', 'statute', array['late_fees']::text[], 'both', 'html', 'Official text of Idaho Code 55-305 on fees charged to residential tenants, including late-payment fees.', 'Idaho Code 55-305', null, 'unverifiable', 'legislature.idaho.gov refused the connection. A site-restricted search returned this exact URL as ''Section 55-305''. Its snippet confirms that fees, including late fees, must be reasonable and may not exceed what the rental agreement allows, with 30 days'' written notice required for new charges. The July 2026 AG manual appendix lists 55-305 as ''Limitation on fees for tenants of a rental property''.', '2026-10-19T00:00:00Z', '{"notes":"Official site refused automated connection; URL confirmed via web search."}'::jsonb),
