  ('5f89d470-c15f-5f36-8764-2622d27f6286', 'MN', 'state', null, 'Tenants'' Rights in Minnesota', 'https://www.lawhelpmn.org/self-help-library/booklet/tenants-rights-minnesota', 'Education for Justice (LawHelpMN)', 'legal_aid', 'other', array['general','repairs_habitability','rent_increase','security_deposit','eviction','retaliation','lead_mold_pests','domestic_violence']::text[], 'tenant', 'html', 'Legal aid booklet on Minnesota tenant rights covering renting, leases, repairs and rent escrow, rent increases, lease termination, illegal landlord tactics and eviction.', null, '08/2026', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"PDF: https://www.lawhelpmn.org/sites/default/files/2026-05/2025_B-06_Tenants_Rights.pdf"}'::jsonb),
  ('6707effa-5e96-5ebf-a4bb-721e082745b7', 'MN', 'state', null, 'Minn. Stat. § 471.9996 - Rent control prohibited', 'https://www.revisor.mn.gov/statutes/cite/471.9996', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'rent_regulation', array['rent_control']::text[], 'both', 'html', 'Statute text generally prohibiting local rent control on private residential property unless approved by voters at a general election.', 'Minn. Stat. § 471.9996', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('a07bc4ab-dfc8-50cf-bcc7-22e180265e2c', 'MN', 'state', null, 'Saint Paul Rent Stabilization', 'https://www.stpaul.gov/departments/safety-inspections/rent-buy-sell-property/renting-property/rent-stabilization', 'City of Saint Paul', 'local_government', 'rent_regulation', array['rent_control','rent_increase']::text[], 'both', 'html', 'City page on the Rent Stabilization Ordinance, the 3% annual limit, exception processes and amendment history.', null, 'May 11, 2026', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Renter page: https://www.stpaul.gov/departments/safety-inspections/rent-buy-sell-property/rent-stabilization/renters; landlord page: https://www.stpaul.gov/departments/safety-inspections/rent-buy-sell-property/rent-stabilization/landlords (both opened)."}'::jsonb),
  ('c995b74b-9e85-5bef-abbf-38b11f3b7ce4', 'MN', 'state', null, 'Housing Help (Minnesota Housing)', 'https://mnhousing.gov/home/housing-help', 'Minnesota Housing Finance Agency', 'state_agency', 'rental_assistance', array['rental_assistance','eviction']::text[], 'tenant', 'html', 'State housing finance agency page listing resources for renters, including Housing Trust Fund rental assistance, the Family Homeless Prevention and Assistance Program and legal help.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"No time-limited statewide emergency rental assistance program is listed; ongoing programs are reached through Continuum of Care or FHPAP providers."}'::jsonb),
  ('fc8e6551-9508-5aca-b27c-9b1f07ee3552', 'MN', 'state', null, 'Minn. Stat. § 504B.147 - Time period for notice to quit or rent increase', 'https://www.revisor.mn.gov/statutes/cite/504B.147', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['rent_increase','lease_termination']::text[], 'both', 'html', 'Statute text on notice periods for ending a tenancy or raising rent when a lease sets different periods for landlord and tenant.', 'Minn. Stat. § 504B.147', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('71821289-7ebd-5a85-b22b-69743766b490', 'MN', 'state', null, 'Minn. Stat. § 504B.161 - Covenants of landlord or licensor', 'https://www.revisor.mn.gov/statutes/cite/504B.161', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute text on the landlord''s non-waivable duties to keep residential premises fit, in repair and in compliance with health and safety laws.', 'Minn. Stat. § 504B.161', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('e045bb29-6021-5bb6-b912-9e01f68cd274', 'MN', 'state', null, 'Minn. Stat. § 504B.177 - Late fees', 'https://www.revisor.mn.gov/statutes/cite/504B.177', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['late_fees']::text[], 'both', 'html', 'Statute text requiring a written agreement for residential late fees and capping them at 8 percent of the overdue rent.', 'Minn. Stat. § 504B.177', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('a77f21ce-30ef-5ca3-9666-827af6d1de17', 'MN', 'state', null, 'Minn. Stat. § 504B.178 - Security deposits', 'https://www.revisor.mn.gov/statutes/cite/504B.178', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['security_deposit']::text[], 'both', 'html', 'Statute text on interest on security deposits, deadlines for return or itemized withholding, penalties, and the limit on withholding last month''s rent.', 'Minn. Stat. § 504B.178', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('38a5f920-fd23-5bd2-9f11-3055129c67c9', 'MN', 'state', null, 'Minn. Stat. § 504B.211 - Residential tenant''s right to privacy', 'https://www.revisor.mn.gov/statutes/cite/504B.211', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['entry_privacy']::text[], 'both', 'html', 'Statute text on landlord entry into a rental unit, including the notice requirement, permitted purposes and exceptions.', 'Minn. Stat. § 504B.211', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('383c7498-850b-527c-b85e-b06e2e1fea61', 'MN', 'state', null, 'Minn. Stat. § 504B.285 - Eviction actions; grounds; retaliation defense', 'https://www.revisor.mn.gov/statutes/cite/504B.285', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['eviction','retaliation']::text[], 'both', 'html', 'Statute text on grounds for eviction actions and the retaliation defense, including retaliatory rent increases.', 'Minn. Stat. § 504B.285', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('8819c0bb-670b-5147-95de-b7f5e4b22ae6', 'MN', 'state', null, 'Minn. Stat. § 504B.321 - Eviction complaint and summons', 'https://www.revisor.mn.gov/statutes/cite/504B.321', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['eviction']::text[], 'both', 'html', 'Statute text on filing an eviction complaint, including the written pre-filing notice for nonpayment cases, required complaint contents and limits on public access to eviction files.', 'Minn. Stat. § 504B.321', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Subd. 1a requires a written notice giving the tenant 14 days to pay or move before a nonpayment eviction is filed. Eviction actions overall: §§ 504B.281-504B.371."}'::jsonb),
  ('a0c257bf-4212-574c-a2fe-8eafc05a31c1', 'MN', 'state', null, 'Minn. Stat. § 504B.385 - Rent escrow action to remedy violations', 'https://www.revisor.mn.gov/statutes/cite/504B.385', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute text on the procedure for tenants to deposit rent with the court when a residential building has violations, and the remedies a court may order.', 'Minn. Stat. § 504B.385', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Related: Tenant Remedies Action, §§ 504B.395-504B.471; emergency remedies, § 504B.381."}'::jsonb),
  ('ab598c68-526f-5419-b026-396a01a82ed1', 'MN', 'state', null, 'Minn. Stat. § 504B.441 - Tenant may not be penalized for complaint', 'https://www.revisor.mn.gov/statutes/cite/504B.441', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['retaliation']::text[], 'both', 'html', 'Statute text barring eviction, increased obligations or reduced services in retaliation for a tenant''s good-faith complaint, with a 90-day burden-of-proof rule.', 'Minn. Stat. § 504B.441', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('6d605d13-f9d8-5e45-bc77-a749fbbe7059', 'MN', 'state', null, 'Minnesota Statutes Chapter 504B - Landlord and Tenant', 'https://www.revisor.mn.gov/statutes/cite/504B', 'Minnesota Office of the Revisor of Statutes', 'state_legislature', 'statute', array['general','repairs_habitability','security_deposit','eviction','retaliation','entry_privacy','late_fees']::text[], 'both', 'html', 'Official text of Minnesota''s residential landlord-tenant chapter, covering leases, covenants, deposits, tenant rights, eviction actions and tenant remedies.', 'Minn. Stat. ch. 504B', '2025', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('02f9e43b-26e8-5cf9-93b3-634f5d9ebbc2', 'MO', 'state', null, 'Submit Consumer Complaint', 'https://app.ago.mo.gov/app/consumercomplaint', 'Missouri Attorney General''s Office', 'state_attorney_general', 'complaint_filing', array['general']::text[], 'tenant', 'html', 'Online consumer complaint form of the Missouri Attorney General.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The form''s categories include ''Real Estate and Construction'' but no landlord-tenant category."}'::jsonb),
  ('d9bfe074-96f3-544f-8e1f-8091229cb131', 'MO', 'state', null, 'Landlord Tenant Forms – 16th Judicial Circuit (Jackson County)', 'https://www.16thcircuit.org/landlord-tenant-forms', '16th Judicial Circuit Court of Missouri (Jackson County)', 'state_court', 'court_self_help', array['eviction','general']::text[], 'both', 'html', 'Circuit court page posting a landlord-tenant booklet, a sample landlord''s petition, trial de novo application and bond forms, service-by-posting motions, a motion to set aside, and sample judgments for rent-and-possession, unlawful detainer and Chapter 441 cases.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Jackson County (Kansas City) circuit only; Missouri landlord-tenant forms vary by circuit. File names show the booklet revised 3-2026 and the motion to set aside 11-2025; the page says users must check it for the latest revised forms."}'::jsonb),
  ('7030b1af-928c-5b08-873b-2d9cc6a42284', 'MO', 'state', null, 'Housing Discrimination - Missouri Commission on Human Rights', 'https://labor.mo.gov/mohumanrights/discrimination/housing', 'Missouri Commission on Human Rights (Department of Labor and Industrial Relations)', 'state_agency', 'fair_housing', array['fair_housing']::text[], 'both', 'html', 'State civil-rights agency page on housing discrimination under the Missouri Human Rights Act.', 'RSMo ch. 213 (Missouri Human Rights Act)', null, 'unverifiable', 'Imperva/Incapsula ''Request unsuccessful'' 403 to both WebFetch and curl, so the content could not be checked. WebSearch confirmation was not possible (session search budget exhausted). The MO AG handbook lists the Missouri Human Rights Commission (877-781-4236) as the housing discrimination contact but gives no URL. Please confirm manually in a browser.', '2026-10-19T00:00:00Z', '{"notes":"URL taken from Legal Services of Missouri''s ''Discrimination In Housing - Missouri'' page. labor.mo.gov returned HTTP 403 to automated requests. The AG handbook gives MCHR phone numbers: 877-781-4236 toll-free."}'::jsonb)
insert into property.legal_resources (id, jurisdiction_code, scope, locality, title, url, publisher, publisher_type, category, topics, audience, format, description, citation, source_updated, verification, verification_note, checked_at, metadata) values
  ('0e51bde5-7c65-5813-b0a0-19c9436e5a44', 'MO', 'state', null, 'Real Estate Disclosures about Potential Lead Hazards', 'https://www.epa.gov/lead/real-estate-disclosure', 'U.S. Environmental Protection Agency', 'federal_agency', 'health_safety', array['lead_mold_pests']::text[], 'landlord', 'html', 'EPA page on the federal Lead-Based Paint Disclosure Rule, which sets the disclosures landlords must make before leasing most pre-1978 housing.', '42 U.S.C. 4852d; 40 CFR 745 Subpart F', '2026-05-27', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Federal rule; applies in every state."}'::jsonb),
  ('d6a18b20-2309-5755-84b8-07088f304344', 'MO', 'state', null, 'HUD Missouri state page', 'https://www.hud.gov/missouri', 'U.S. Department of Housing and Urban Development', 'federal_agency', 'hud_state_page', array['rental_assistance','general']::text[], 'tenant', 'html', 'HUD''s Missouri state page, which MHDC links to for Missouri eviction-prevention and rent-relief resources.', null, null, 'unverifiable', 'Cloudflare 403 bot wall on hud.gov, from both WebFetch and curl. The only evidence is that MHDC''s renters page links https://www.hud.gov/missouri#RentRelief. That anchor dates from the Emergency Rental Assistance (ERA) era, and the hud.gov 2025 redesign may have restructured state pages, so it is unconfirmed whether this URL still resolves to Missouri content or a ''RentRelief'' section. Verify in a browser before shipping.', '2026-10-19T00:00:00Z', '{"notes":"URL taken from MHDC''s renters page (it links https://www.hud.gov/missouri#RentRelief). hud.gov returned Cloudflare 403, so it was not confirmed that this page carries HUD''s Missouri tenant-rights content."}'::jsonb),
  ('405a8ec2-7466-542b-915b-62ecff023aaa', 'MO', 'state', null, 'HUD: Missouri resources', 'https://www.hud.gov/states/missouri', 'U.S. Department of Housing and Urban Development', 'federal_agency', 'hud_state_page', array['general','eviction','rental_assistance','fair_housing']::text[], 'both', 'html', 'HUD''s Missouri page with rent relief and eviction resources, discrimination complaint links, housing-quality contacts and local HUD offices.', null, null, 'unverifiable', 'hud.gov blocks automated checks; URL follows the post-2025 redesign pattern confirmed via Internet Archive captures.', '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('e38fb590-5117-50c3-95b4-90c173a7dca5', 'MO', 'state', null, 'Housing - Legal Services of Missouri', 'https://www.lsmo.org/topics/2305/housing', 'Legal Services of Missouri', 'legal_aid', 'legal_aid_directory', array['eviction','fair_housing','general']::text[], 'tenant', 'html', 'Statewide legal aid housing page with eviction, renters''-rights and housing-discrimination resources and links to the four regional legal aid programs.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"LawHelp.org''s state finder points Missouri to lsmo.org; lawhelpmo.org did not resolve."}'::jsonb),
  ('98f6c269-8e78-5290-a471-8ee5ae9f91a1', 'MO', 'state', null, 'Landlord Tenant Law', 'https://ago.mo.gov/get-help/programs-services-from-a-z/landlord-tenant-law/', 'Missouri Attorney General''s Office', 'state_attorney_general', 'official_guide', array['general','repairs_habitability','fair_housing']::text[], 'both', 'html', 'Attorney General web page summarizing basic landlord and tenant responsibilities, with links to the handbook, the statutes and the consumer complaint form.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('81bdfaa6-9936-56d4-b0cf-19180db654ca', 'MO', 'state', null, 'Missouri''s Landlord-Tenant Law: The Rights & Responsibilities of Landlords & Tenants', 'https://ago.mo.gov/wp-content/uploads/Landlord-Tenant-Law-CH.pdf', 'Missouri Attorney General''s Office', 'state_attorney_general', 'official_guide', array['general','repairs_habitability','security_deposit','eviction','rent_increase','lease_termination','fair_housing','military','utilities']::text[], 'both', 'pdf', 'Attorney General handbook on Missouri landlord and tenant rights and duties, covering leases, rent increases under oral agreements, security deposits, repair-and-deduct, eviction and discrimination.', 'RSMo chs. 441, 534, 535', 'September 2025', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Covers the 2-month deposit cap, 30-day deposit return, the narrow 14-day-notice repair-and-deduct remedy (greater of one-half month''s rent or $300), one month''s notice to raise rent under oral agreements, and the military 15-day lease termination."}'::jsonb),
  ('a2a25bbd-cce3-5f28-8d3b-3d5615d9ffd9', 'MO', 'city', 'Kansas City, MO', 'Landlord Information: Healthy Homes Rental Inspection Program', 'https://kcmo.gov/city-hall/departments/health/environmental-health-services/landlord-information-healthy-homes-rental-inspection-program', 'City of Kansas City, Missouri Health Department', 'local_government', 'other', array['general','repairs_habitability']::text[], 'landlord', 'html', 'City Health Department page on the Healthy Homes Rental Inspection Program, which requires rental property owners to register and hold an annual rental permit under Ordinance 180248.', 'KCMO Ordinance 180248', null, 'unverifiable', 'Redirects to www.kcmo.gov, which returns an Akamai 403 for every path, including the home page, robots.txt and a made-up path, so the page''s existence is NOT confirmed. WebSearch budget was used up. Partial check: the KC Legistar API shows Ordinance 180248 called the Aug 7, 2018 election on the initiative-petition residential rental inspection program, enacting it subject to voter approval. The ''annual rental permit'' detail is unverified. Check by hand in a browser.', '2026-10-19T00:00:00Z', '{"notes":"Covers rental registration. kcmo.gov returned HTTP 403 (Akamai) to every automated request, so these details come only from search-result snippets: $20 application fee plus $20 per unit per year, 816-513-6464. Per a 2024 city auditor scope statement, the program also inspects tenant health and safety complaints. Verify manually."}'::jsonb),
  ('ffdec359-53e8-5fd2-9b4b-8b6bc537729c', 'MO', 'state', null, 'Missouri Tenant Help', 'https://motenanthelp.org/', 'Missouri legal aid organizations (HUD-funded)', 'legal_aid', 'other', array['eviction']::text[], 'tenant', 'html', 'Free self-help site for Missouri renters facing eviction, with plain-language explanations of eviction case types and a tool that prepares a court filing.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The rent-and-possession explainer page was last updated 06/22/2023."}'::jsonb),
  ('b30ef351-6b48-5fc8-b3a0-e0ac5eeb8583', 'MO', 'state', null, 'Renters - Missouri Housing Development Commission', 'https://mhdc.com/services/housing-services/renters/', 'Missouri Housing Development Commission', 'state_agency', 'rental_assistance', array['rental_assistance']::text[], 'tenant', 'html', 'State housing finance agency page pointing renters to rental-assistance information, eviction-prevention resources, an affordable housing locator and Community Action Agencies.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"No statewide emergency rental assistance program is listed as open. The page refers renters to HUD resources and the 19 Community Action Agencies."}'::jsonb),
  ('02c2a302-dc8b-5e3c-b737-391f2c82aea1', 'MO', 'state', null, 'Missouri Revised Statutes (Revisor of Statutes)', 'https://revisor.mo.gov/main/Home.aspx', 'Missouri Revisor of Statutes, Committee on Legislative Research', 'state_legislature', 'statute', array['general','repairs_habitability','security_deposit','eviction','rent_control']::text[], 'both', 'html', 'Official online Missouri Revised Statutes, including chapters 441, 534 and 535 on landlord-tenant law and eviction.', 'RSMo chs. 441, 534, 535 (incl. § 441.234 repair-and-deduct, § 535.300 security deposits)', null, 'unverifiable', 'revisor.mo.gov refuses the connection from this (non-US) network. curl over plain http returned a ''Network Security Appliance ... Gateway GEO-IP Filter Alert'' block page. The MO AG Landlord Tenant Law page links to this exact URL as ''Mo Statutes'', so it is the official Revisor site. It should work for US users, but a link checker running from outside the US will fail.', '2026-10-19T00:00:00Z', '{"notes":"Linked from the Missouri AG''s Landlord Tenant Law page, and the AG handbook names chapters 441, 534 and 535. revisor.mo.gov refused WebFetch connections (ECONNREFUSED) and served a ''Web Site Blocked'' page to curl. Section deep links (e.g., OneSection.aspx?section=535.300) could not be verified, so none are listed. The section numbers in the citation field are recalled, not checked this session."}'::jsonb),
  ('76b381f3-29dd-5ded-9b4b-a1313dca79fe', 'MS', 'state', null, 'Consumer Complaint Form', 'https://portal.ago.ms.gov/public/?q=node/403', 'Mississippi Attorney General''s Office', 'state_attorney_general', 'complaint_filing', array['general']::text[], 'tenant', 'html', 'Online consumer complaint form on the Mississippi Attorney General''s public portal.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The form is generic and does not mention landlord-tenant or housing complaints by name."}'::jsonb),
  ('597301b7-dfc3-5be1-be15-9b083b8d599e', 'MS', 'state', null, 'Consumer Protection Division', 'https://attorneygenerallynnfitch.com/divisions/consumer-protection/', 'Mississippi Attorney General''s Office', 'state_attorney_general', 'complaint_filing', array['general']::text[], 'both', 'html', 'Attorney General Consumer Protection Division page that lists consumer statutes, including the Residential Landlord and Tenant Act, and links to the consumer complaint form.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The page has no other landlord-tenant guidance apart from the Act PDF."}'::jsonb),
  ('a34455bd-c610-597e-bc30-e8ad515c264d', 'MS', 'state', null, 'Housing Issues', 'https://msatjc.org/housing-issues', 'Mississippi Access to Justice Commission', 'other', 'court_self_help', array['eviction','general','fair_housing']::text[], 'both', 'html', 'Self-help page for people without a lawyer that collects landlord/tenant and eviction resources, eviction self-help videos and fair housing links.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Used in place of the state judiciary''s own self-help page, because courts.ms.gov returned HTTP 500 errors throughout this session."}'::jsonb),
  ('35cb1cfc-979c-5b5b-8b3e-55fba7cfc79b', 'MS', 'state', null, 'Discrimination In Housing', 'https://msbar.org/article/discrimination-in-housing/', 'The Mississippi Bar', 'bar_association', 'fair_housing', array['fair_housing']::text[], 'both', 'html', 'Mississippi Bar article on federal and state fair housing protections, with contact details for HUD''s Fair Housing and Equal Opportunity office in Jackson.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"No state fair-housing enforcement agency was identified; the article points complainants to HUD FHEO."}'::jsonb),
  ('71072512-0c5f-5166-8b2a-01a9e5dda814', 'MS', 'state', null, 'HUD Office of Fair Housing and Equal Opportunity', 'https://www.hud.gov/program_offices/fair_housing_equal_opp', 'U.S. Department of Housing and Urban Development', 'federal_agency', 'fair_housing', array['fair_housing']::text[], 'both', 'html', 'HUD''s fair housing office page, which covers filing a housing discrimination complaint.', null, null, 'unverifiable', 'hud.gov returns a 403 Cloudflare bot wall (''Sorry, you have been blocked'') to both WebFetch and curl, so the content and any post-2025-redesign redirect could not be checked. WebSearch could not be used either (session search budget exhausted). The only evidence is that msatjc.org/housing-issues still links this exact URL. Because of the 2025 redesign, please open it in a browser before shipping and confirm it does not land on a generic page.', '2026-10-19T00:00:00Z', '{"notes":"Linked from the MS Access to Justice Commission housing page. hud.gov returned Cloudflare 403 to every automated request, and after HUD''s 2025 redesign this older URL may redirect, so it needs checking."}'::jsonb),
