  ('ed35e9cf-3881-526a-a39d-12567cdaa0ff', 'NH', 'state', null, 'RSA 540-A:3 - Certain acts prohibited', 'https://gc.nh.gov/rsa/html/LV/540-A/540-A-3.htm', 'New Hampshire General Court', 'state_legislature', 'statute', array['utilities','entry_privacy','eviction','lead_mold_pests']::text[], 'both', 'html', 'Statute section listing acts landlords may not take, such as willful utility interruption, lockouts and certain entries, and including bed bug provisions (paragraph V-c).', 'RSA 540-A:3', null, 'unverifiable', 'Unreachable (socket hang-up). The claim that bed-bug provisions sit at ''paragraph V-c'' is unverified. 603 Legal Aid confirms that RSA 540-A bars utility shutoffs, lockouts and unauthorized entry and requires pest investigation within 7 days.', '2026-10-19T00:00:00Z', '{"notes":"URL from a 603 Legal Aid bed bugs article. The legislature site was not reachable for automated fetches."}'::jsonb),
  ('886a4a9e-88f6-5540-b19f-422141abb99a', 'NH', 'state', null, 'RSA 540:13-d - Defenses to violations of fitness (rent withholding)', 'https://www.gencourt.state.nh.us/rsa/html/LV/540/540-13-d.htm', 'New Hampshire General Court', 'state_legislature', 'statute', array['repairs_habitability','eviction']::text[], 'both', 'html', 'Statute section setting the conditions under which code violations can be raised as a defense when rent is withheld in a nonpayment eviction.', 'RSA 540:13-d', null, 'unverifiable', '403. 603 Legal Aid confirms RSA 540:13-d is the rent-withholding defense, which it calls ''Defenses to Violations of Fitness''.', '2026-10-19T00:00:00Z', '{"notes":"URL from 603 Legal Aid''s ''Withholding Rent'' article. The legislature site was not reachable."}'::jsonb),
  ('0876ed35-2603-5a2e-9e1a-13ead3da65f4', 'NH', 'state', null, 'RSA 540:13-e - Bed bugs', 'https://gc.nh.gov/rsa/html/LV/540/540-13-e.htm', 'New Hampshire General Court', 'state_legislature', 'statute', array['lead_mold_pests']::text[], 'both', 'html', 'Statute section on bed bug remediation, remediation costs and repayment agreements between landlords and tenants.', 'RSA 540:13-e', null, 'unverifiable', 'Unreachable (socket hang-up). Neither the ''Bed bugs'' heading nor the section''s existence could be confirmed from any source, so verify before shipping.', '2026-10-19T00:00:00Z', '{"notes":"URL from a 603 Legal Aid bed bugs article. The legislature site was not reachable."}'::jsonb),
  ('f816262f-e804-5fb3-a44a-343b2aa65ad2', 'NH', 'state', null, 'RSA Chapter 354-A - Law Against Discrimination', 'https://gencourt.state.nh.us/rsa/html/NHTOC/NHTOC-XXXI-354-A.htm', 'New Hampshire General Court', 'state_legislature', 'statute', array['fair_housing']::text[], 'both', 'html', 'Table of contents for New Hampshire''s anti-discrimination law, which covers housing.', 'RSA ch. 354-A', null, 'unverifiable', 'Unreachable (socket hang-up), and no search was available to confirm it.', '2026-10-19T00:00:00Z', '{"notes":"URL from 603 Legal Aid''s ''Fair Housing Laws'' article. The legislature site was not reachable."}'::jsonb),
  ('3fbd9976-edc3-55cc-ba47-7cd711acf9ac', 'NH', 'state', null, 'RSA Chapter 540-A - Prohibited Practices and Security Deposits', 'https://gc.nh.gov/rsa/html/LV/540-A/540-A-mrg.htm', 'New Hampshire General Court', 'state_legislature', 'statute', array['security_deposit','entry_privacy','utilities','general']::text[], 'both', 'html', 'Official text of New Hampshire''s chapter on prohibited landlord practices and residential security deposits.', 'RSA ch. 540-A (security deposits at RSA 540-A:5 to 540-A:8)', null, 'unverifiable', 'The NH General Court servers refused automated access: 403 and socket hang-ups on WebFetch, TLS handshake failure on curl, for both gc.nh.gov and gencourt.state.nh.us. 603 Legal Aid links RSA 540-A at https://www.gencourt.state.nh.us/rsa/html/nhtoc/nhtoc-lv-540-a.htm. This list mixes the gc.nh.gov and gencourt.state.nh.us hosts, so pick one consistently.', '2026-10-19T00:00:00Z', '{"notes":"URL taken from a link on 603 Legal Aid''s RSA 540-A petition article. gc.nh.gov and gencourt.state.nh.us refused or reset automated connections in this session."}'::jsonb),
  ('dc6b5c79-2b39-541c-8e8c-83b78f9b42d2', 'NJ', 'state', null, 'Bureau of Housing Inspection - NJ DCA', 'https://www.nj.gov/dca/codes/offices/housinginspection.shtml', 'New Jersey Department of Community Affairs, Division of Codes and Standards', 'state_agency', 'code_enforcement', array['repairs_habitability']::text[], 'both', 'html', 'DCA bureau page on enforcement of the Hotel and Multiple Dwelling Law for buildings with three or more units, with inspection and code-compliance contacts.', 'N.J.S.A. 55:13A; N.J.A.C. 5:10', null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Statute PDF: https://www.nj.gov/dca/codes/codreg/pdf_regs/55_13A.pdf (current through L.2025, c.152)."}'::jsonb),
  ('a3e4d872-e8dc-5f8e-8155-781115640d43', 'NJ', 'city', 'Hoboken, NJ', 'Division of Health (housing inspections, heat and rodent complaints)', 'https://www.hobokennj.gov/departments/health-department', 'City of Hoboken, Division of Health', 'local_government', 'code_enforcement', array['repairs_habitability','utilities','lead_mold_pests']::text[], 'tenant', 'html', 'City health division page covering housing-unit inspections, the heat-season requirement (Oct 1 to May 1), and how to report heat or rodent complaints by phone or through the city''s online concern form.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Phone (201) 420-1620. Online concern form: https://www.sdlportal.com/towns/nj/hudson/hoboken/requests/complaint (vendor-run city portal). For multiple dwellings (3+ units), the NJ DCA Bureau of Housing Inspection is the state-level inspector."}'::jsonb),
  ('5e289c28-fd74-5f2a-8cfd-3eb3d10cee0e', 'NJ', 'state', null, 'NJBIAS - File a Civil Rights Complaint', 'https://bias.njcivilrights.gov/en-US/', 'New Jersey Office of Attorney General, Division on Civil Rights', 'state_attorney_general', 'complaint_filing', array['fair_housing']::text[], 'tenant', 'html', 'Online portal for filing discrimination complaints, including housing discrimination, with the Division on Civil Rights.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The URL is linked as ''File A Complaint'' from the DCR and AG pages, and it returned HTTP 200, but the app is JavaScript-rendered so its content could not be read."}'::jsonb),
