  ('35466bf2-b193-58cf-868f-ee0b0a5a906a', 'NJ', 'state', null, 'NJ Eviction Guide', 'https://evictionguide.dca.nj.gov/en', 'New Jersey Department of Community Affairs, Office of Eviction Prevention', 'state_agency', 'court_self_help', array['eviction']::text[], 'tenant', 'html', 'Interactive DCA tool that gives general eviction-process guidance and links to free legal help in English and Spanish.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Reached via evictionguide.nj.gov, which redirects here. This is a state-agency tool, not a court page. See the gaps list for the NJ Courts page."}'::jsonb),
