  ('039c7bd3-7cac-5234-818d-6b5fb2927daf', 'PA', 'city', 'Pittsburgh, PA', 'PLI Code Enforcement', 'https://www.pittsburghpa.gov/Business-Development/Permits-Licenses-and-Inspections/Enforcement', 'City of Pittsburgh - Department of Permits, Licenses, and Inspections', 'local_government', 'code_enforcement', array['repairs_habitability']::text[], 'both', 'html', 'PLI page on property-maintenance code enforcement and how residents file complaints through 311, which are forwarded to code enforcement inspectors.', null, '2026-09-14', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Page title reads ''Enforcement - Pittsburgh, PA''."}'::jsonb),
  ('e55b36b2-44e3-5283-9a4c-a5cf3cfffd6e', 'PA', 'city', 'Philadelphia, PA', 'Report a problem with a building, lot, or street', 'https://www.phila.gov/services/property-lots-housing/report-a-problem-with-a-building-lot-or-street/', 'City of Philadelphia - Department of Licenses and Inspections / Philly311', 'local_government', 'code_enforcement', array['repairs_habitability']::text[], 'tenant', 'html', 'City page for reporting rental properties that violate City codes, and interior or exterior maintenance problems, through the 311 online form or by phone.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('988e9df1-eef0-54ea-9c8c-bfc6495ebb4f', 'PA', 'city', 'Philadelphia, PA', 'File a complaint about unfair rental practices', 'https://www.phila.gov/services/crime-law-justice/report-a-crime-or-concern/discrimination-and-unfair-practices/file-a-complaint-about-unfair-rental-practices/', 'City of Philadelphia - Fair Housing Commission', 'local_government', 'complaint_filing', array['retaliation','repairs_habitability','eviction','lease_termination']::text[], 'tenant', 'html', 'City service page on eligibility, required documents and intake options for filing an unfair-rental-practices complaint with the Fair Housing Commission.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"May resolve to /services/crime-law-justice/report-a-crime-or-concern/discrimination-and-unfair-practices/file-a-complaint-about-unfair-rental-practices/."}'::jsonb),
  ('3057aaf2-f9d6-5d94-94df-e5ae129103d5', 'PA', 'city', 'Pittsburgh, PA', 'Pittsburgh 311', 'https://www.pittsburghpa.gov/Resident-Services/311', 'City of Pittsburgh', 'local_government', 'complaint_filing', array['repairs_habitability']::text[], 'both', 'html', 'City 311 page with the phone numbers and online form for submitting service requests, including property-maintenance complaints.', null, '2026-09-29', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('20028a44-fbfd-520f-96bc-7535354be692', 'PA', 'state', null, 'Submit a Consumer Complaint', 'https://www.attorneygeneral.gov/submit-a-complaint/consumer-complaint/', 'Pennsylvania Office of Attorney General - Bureau of Consumer Protection', 'state_attorney_general', 'complaint_filing', array['general']::text[], 'tenant', 'html', 'Online form for filing a consumer complaint with the Attorney General''s Bureau of Consumer Protection, which the AG guide names as the channel for landlord-tenant problems.', null, null, 'unverifiable', 'WebFetch and curl both return 403 (redirect to /blocked/). The AG''s own tenant guide PDF cites this exact URL as the online consumer complaint channel for landlord-tenant problems.', '2026-10-19T00:00:00Z', '{"notes":"attorneygeneral.gov returned HTTP 403 to automated fetches. The URL comes from the AG''s own tenant-landlord guide (opened). The guide also lists the hotline 800-441-2555."}'::jsonb),
  ('53559f42-6eb9-561b-81e6-9b42b31fc6b4', 'PA', 'state', null, 'Unfair rental practices - Philadelphia Fair Housing Commission', 'https://www.phila.gov/departments/fair-housing-commission/tenant-protections/unfair-rental-practices/', 'City of Philadelphia - Fair Housing Commission', 'local_government', 'complaint_filing', array['retaliation','eviction','lease_termination','domestic_violence']::text[], 'both', 'html', 'City page explaining unfair rental practices under Philadelphia Code § 9-804, including retaliation and unlawful eviction, and how to file a complaint with the Fair Housing Commission.', 'Phila. Code § 9-804', null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Philadelphia only. Complaint service page: https://www.phila.gov/services/crime-law-justice/report-a-crime-or-concern/discrimination-and-unfair-practices/file-a-complaint-about-unfair-rental-practices/"}'::jsonb),
  ('0e01f8e9-7aa8-5abb-a4e5-c19f2f3ca311', 'PA', 'state', null, 'Forms for the Public - Pennsylvania Courts', 'https://www.pacourts.us/forms/for-the-public', 'Administrative Office of Pennsylvania Courts (Unified Judicial System)', 'state_court', 'court_self_help', array['eviction']::text[], 'both', 'html', 'Unified Judicial System page of court forms for the public, including forms used in magisterial district court landlord-tenant cases.', null, null, 'unverifiable', 'Returns an Akamai ''Access Denied'' (403) to WebFetch and curl. A web search confirms that pacourts.us hosts the AOPC 310A Landlord/Tenant Complaint form, but did not surface this exact page.', '2026-10-19T00:00:00Z', '{"notes":"pacourts.us returned HTTP 403 to automated fetches. The URL was confirmed as the redirect target of PALawHelp''s ''Forms - Pennsylvania Courts'' resource (last reviewed June 1, 2026)."}'::jsonb),
  ('38fd0657-bada-5dc0-a86a-35ca44e23d22', 'PA', 'state', null, 'Tenant Landlord Digital Assistant (T/LDA) - Philadelphia Municipal Court', 'https://www.courts.phila.gov/municipal/civil/Landlord-Tenant-Cases/tlda/', 'First Judicial District of Pennsylvania (Philadelphia Courts)', 'state_court', 'court_self_help', array['eviction']::text[], 'both', 'html', 'Philadelphia Municipal Court page for an online guide to landlord-tenant cases for non-payment of rent, with links to starting, responding to and attending landlord-tenant hearings.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Philadelphia County only. Related pages include /municipal/civil/Landlord-Tenant-Cases/responding-to-a-landlord-tenant-case/."}'::jsonb),
  ('c63c07dc-0d10-58d1-aebe-98435a162ec1', 'PA', 'city', 'Pittsburgh, PA', 'Commission on Human Relations FAQs', 'https://www.pittsburghpa.gov/City-Government/Boards-Authorities-Commissions/List-of-Boards-Authorities-Commissions/Commission-on-Human-Relations/About-PghCHR/FAQs', 'City of Pittsburgh - Commission on Human Relations', 'local_government', 'fair_housing', array['fair_housing']::text[], 'tenant', 'html', 'FAQ from the City commission that investigates housing-discrimination complaints within Pittsburgh, covering protected classes, filing deadlines and referrals for areas outside the city.', null, '2026-07-09', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Pittsburgh has no dedicated tenant-protection office. PghCHR is the closest local body."}'::jsonb),
  ('882d4773-4ead-5f6d-b793-c92a33d6a222', 'PA', 'state', null, 'File a Housing & Commercial Property Discrimination Complaint', 'https://www.pa.gov/services/phrc/file-a-housing---commercial-property-discrimination-complaint', 'Pennsylvania Human Relations Commission', 'state_agency', 'fair_housing', array['fair_housing','accessibility']::text[], 'tenant', 'html', 'State civil rights agency page explaining housing discrimination under the Pennsylvania Human Relations Act and providing the intake questionnaire for complaints.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Intake form available in English and Spanish."}'::jsonb)
