  ('d5748ee2-81a9-5dc2-95bd-18a27fb3e554', 'PA', 'city', 'Philadelphia, PA', 'Fair Housing Commission', 'https://www.phila.gov/departments/fair-housing-commission/', 'City of Philadelphia - Fair Housing Commission', 'local_government', 'other', array['repairs_habitability','retaliation','fair_housing','eviction']::text[], 'both', 'html', 'Homepage of the City commission that enforces Philadelphia''s Fair Housing Ordinance, holds hearings on unsafe rental conditions and unfair rental practices, and educates tenants and landlords.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Walk-in and appointment hours differ across City pages."}'::jsonb),
  ('61184729-5c3a-528e-8d35-9e4e445657dd', 'PA', 'city', 'Philadelphia, PA', 'Get free legal help to avoid eviction (Right to Counsel)', 'https://www.phila.gov/services/property-lots-housing/get-free-legal-help-to-avoid-eviction/', 'City of Philadelphia - Division of Housing and Community Development', 'local_government', 'other', array['eviction','lease_termination']::text[], 'tenant', 'html', 'City page describing the Right to Counsel program, which provides free lawyers to eligible low-income renters facing eviction, lease termination or PHA subsidy termination.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Eligibility depends on income (200% of the federal poverty level) and covered ZIP codes."}'::jsonb),
  ('2fc924da-a2b3-52cc-b140-0e612f4ffea1', 'PA', 'city', 'Pittsburgh, PA', 'Registrations (PLI) - Residential Housing Rental Permit Program / Rental Registry', 'https://www.pittsburghpa.gov/Business-Development/Permits-Licenses-and-Inspections/Licensing/Registrations', 'City of Pittsburgh - Office of the Mayor / PLI', 'local_government', 'other', array['general']::text[], 'landlord', 'html', 'City news release describing PLI''s rental permit and registration program for long- and short-term rentals, registration through OneStopPGH, and inspections against the property maintenance code.', null, '2025-02-14', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Replaced outdated link | This is a news release, not a program page. The former program page, pittsburghpa.gov/pli/rental-registration, now returns 404. Enforcement status is unclear (see notes)."}'::jsonb),
  ('504a909e-8a72-569b-b660-8490edec5422', 'PA', 'city', 'Philadelphia, PA', 'Rental and property licenses', 'https://www.phila.gov/departments/department-of-licenses-and-inspections/licenses/rental-and-property-licenses/', 'City of Philadelphia - Department of Licenses and Inspections', 'local_government', 'other', array['general']::text[], 'landlord', 'html', 'L&I overview of the Rental License required to rent dwelling, rooming or sleeping units in Philadelphia, and related affidavits and limited-lodging licenses.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The application page it links to is https://www.phila.gov/services/permits-violations-licenses/get-a-license/business-licenses/rental-and-property/get-a-rental-license/ (not opened)."}'::jsonb),
