  ('103dbbbb-a673-548d-a0fb-567d3848ff7d', 'PA', 'state', null, 'The Landlord and Tenant Act of 1951 (Act 20 of 1951)', 'https://www.legis.state.pa.us/wu01/li/li/us/pdf/1951/0/0020..pdf', 'Pennsylvania General Assembly', 'state_legislature', 'statute', array['general','security_deposit','eviction','lease_termination']::text[], 'both', 'pdf', 'Official text of Pennsylvania''s Landlord and Tenant Act of 1951 published by the Pennsylvania General Assembly.', '68 P.S. § 250.101 et seq. (security deposits §§ 250.511a-250.512; notice to quit § 250.501; appeals § 250.513)', null, 'unverifiable', 'The host (216.157.112.153, shared with palegis.us) refused or timed out for WebFetch and curl. A web search indexes this exact URL as the official Act 20 text. Caveats: the General Assembly''s current domain is palegis.us (pa.gov footers link there), so this legacy URL may break. Act 88 of 2024 (SB 1236) amended §§ 102 and 501, so confirm the PDF includes it.', '2026-10-19T00:00:00Z', '{"notes":"The General Assembly sites (legis.state.pa.us and palegis.us) refused connections from this environment. This URL was confirmed by a search result in this session. The section numbers listed come from the PA Attorney General guide, which was opened. Section-level official deep links could not be verified."}'::jsonb),
  ('4fdfbc78-9109-5685-9e8d-eb6fafcb3f93', 'RI', 'city', 'Providence, RI', 'How to Report a Housing Code Violation (PVD311 KA-01062)', 'https://311.providenceri.gov/knowledgebase/article/KA-01062/en-us', 'City of Providence (PVD311 / Department of Inspection and Standards)', 'local_government', 'code_enforcement', array['repairs_habitability','utilities']::text[], 'tenant', 'html', 'City 311 knowledge article explaining how to report substandard housing conditions under the Rhode Island Property Maintenance Code, and the Department of Inspection and Standards'' enforcement steps.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"DIS Code Enforcement Division: 444 Westminster St, 401.680.5201; pvd311@providenceri.gov. A downloadable PDF version is attached to the article."}'::jsonb),
  ('871667b1-6f35-59e6-948a-7f3d028c62b1', 'RI', 'state', null, 'Rhode Island Rental Registry', 'https://www.rentalregistry.ri.gov/', 'Rhode Island Department of Health', 'state_agency', 'code_enforcement', array['lead_mold_pests','general']::text[], 'landlord', 'html', 'Statewide mandatory registry for Rhode Island residential rental units, administered by the Department of Health.', 'R.I. Gen. Laws § 34-18-58', null, 'unverifiable', 'Returns 301 Moved Permanently to https://health.ri.gov/rentalregistry, which shows a Cloudflare challenge (403). RIHousing''s 2026 renters page links this URL as the ''Rhode Island Rental Registry''. Consider linking the health.ri.gov/rentalregistry destination directly.', '2026-10-19T00:00:00Z', '{"notes":"Redirects to https://health.ri.gov/rentalregistry, which returned a Cloudflare challenge (HTTP 403). The URL is confirmed as a link on RIHousing''s renters page."}'::jsonb),
  ('0e5b5a38-3e88-5ad2-9b20-a2bceec9f08d', 'RI', 'state', null, 'Affidavit of Compliance With the Statewide Mandatory Rental Registry (DC-108)', 'https://www.courts.ri.gov/Forms/Affidavit%20of%20Compliance%20With%20the%20Statewide%20Mandatory%20Rental%20Registry.pdf', 'Rhode Island Judiciary - District Court', 'state_court', 'court_self_help', array['eviction','lead_mold_pests']::text[], 'landlord', 'pdf', 'District Court affidavit in which a landlord attests to registering with the Department of Health and filing a lead certificate of conformance or exemption under R.I. Gen. Laws § 34-18-58.', 'R.I. Gen. Laws § 34-18-58', 'Form revised October 21, 2024 (file modified 2026-08-27)', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('f51ed162-e50a-5da4-94ff-f36b25a01381', 'RI', 'state', null, 'Complaint and Motion for Temporary Restraining Order - Tenant Against Landlord (District Court form)', 'https://www.courts.ri.gov/Forms/Complaint%20and%20Motion%20for%20Temporary%20Restraining%20Order%20-%20Tenant%20Against%20Landlord.pdf', 'Rhode Island Judiciary - District Court', 'state_court', 'court_self_help', array['general']::text[], 'tenant', 'pdf', 'District Court form for a tenant''s complaint and motion for a temporary restraining order against a landlord.', null, '2024-07-01 (file last modified)', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"A matching landlord-against-tenant form is in the same library."}'::jsonb),
