  ('2f901111-6a47-5dbd-a33c-2e280f4c40ab', 'RI', 'state', null, 'Eviction - Answer (Defendant/Tenant) (District Court form)', 'https://www.courts.ri.gov/Forms/Eviction%20-%20Answer%20Defendant-Tenant.pdf', 'Rhode Island Judiciary - District Court', 'state_court', 'court_self_help', array['eviction']::text[], 'tenant', 'pdf', 'District Court answer form for tenants responding to an eviction complaint.', null, '2024-07-02 (file last modified)', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
