  ('8fc9f1d3-93fc-5b8e-92a2-6795ad338eda', 'US', 'federal', null, 'Renovation, Repair and Painting Program: Property Managers', 'https://www.epa.gov/lead/renovation-repair-and-painting-program-property-managers', 'U.S. Environmental Protection Agency', 'federal_agency', 'health_safety', array['lead_mold_pests','repairs_habitability']::text[], 'landlord', 'html', 'EPA page explaining RRP Rule requirements for property managers and landlords of pre-1978 buildings when repair or renovation work disturbs paint.', null, '2026-05-27', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"EPA has no separate landlord RRP page, so this is the closest match. The program hub is /lead/renovation-repair-and-painting-program (updated 2026-06-17)."}'::jsonb),
  ('8d9d8423-0493-56a3-b7bb-39c4f940acb9', 'US', 'federal', null, 'Renovation, Repair and Painting Program: Renters', 'https://www.epa.gov/lead/renovation-repair-and-painting-program-renters', 'U.S. Environmental Protection Agency', 'federal_agency', 'health_safety', array['lead_mold_pests','repairs_habitability']::text[], 'tenant', 'html', 'EPA page describing what renters should receive and expect when lead-disturbing repair or renovation work is done in pre-1978 housing.', null, '2026-10-09', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
