  ('71a77b50-4579-5419-a9bc-7ef7459a11be', 'US', 'federal', null, 'Armed Forces Legal Assistance (AFLA) Legal Services Locator', 'https://legalassistance.law.af.mil/', 'U.S. Air Force Judge Advocate General''s Corps (DoD)', 'federal_agency', 'legal_aid_directory', array['military']::text[], 'tenant', 'html', 'Department of Defense locator for military legal assistance offices that provide free general legal services to eligible servicemembers and families.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('5fb10e6a-4740-511a-b1f0-9e9f009efd5b', 'US', 'federal', null, 'Find a lawyer for affordable legal aid (USAGov)', 'https://www.usa.gov/legal-aid', 'USAGov (General Services Administration)', 'federal_agency', 'legal_aid_directory', array['general','military','accessibility']::text[], 'both', 'html', 'USAGov page listing programs and organizations that provide free or low-cost legal help, including resources for veterans, seniors and people with disabilities.', null, '2025-11-17', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('b352d142-c51a-5f56-941c-bd8079ef8828', 'US', 'national', null, 'I Need Legal Help (LSC Find Legal Aid)', 'https://www.lsc.gov/about-lsc/what-legal-aid/i-need-legal-help', 'Legal Services Corporation', 'other', 'legal_aid_directory', array['general','eviction']::text[], 'tenant', 'html', 'Legal Services Corporation tool for finding the LSC-funded civil legal aid organization that serves a given address or area.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"LSC is the congressionally created nonprofit that funds civil legal aid. /about-lsc/what-legal-aid/get-legal-help redirects here. The locator is embedded in the page, with no standalone URL or API."}'::jsonb),
  ('526b5e4b-dc4b-53d4-b4ea-c55074150486', 'US', 'national', null, 'LawHelp.org', 'https://www.lawhelp.org/', 'Pro Bono Net / Scale Justice', 'nonprofit', 'legal_aid_directory', array['general','eviction']::text[], 'tenant', 'html', 'National entry point to the state LawHelp sites (56 states and territories), which carry legal information and directories of free legal help from nonprofit providers.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"No API or feed. The disclaimer says ''This is not legal advice'' and ''© 2001-2026, Scale Justice, All Rights Reserved''. Example state site: https://www.lawhelpny.org/issues/housing."}'::jsonb),
  ('32ab9f66-8a2b-50ba-9833-914725844468', 'US', 'national', null, 'LawHelp.org - Find Legal Help by State', 'https://www.lawhelp.org/find-help', 'Pro Bono Net', 'nonprofit', 'legal_aid_directory', array['general','eviction','repairs_habitability']::text[], 'tenant', 'html', 'National directory linking to each state''s nonprofit legal aid website with free legal information and provider listings.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Run by Pro Bono Net with legal aid partners. HUD state pages link several network sites (LawHelpCA, LawHelpNY, TexasLawHelp)."}'::jsonb),
  ('0abe0bf9-44b6-5469-82c4-f8ddfc628a00', 'US', 'federal', null, 'Legal Assistance for Service Members and Families (Military OneSource)', 'https://www.militaryonesource.mil/benefits/legal-assistance-for-service-members-and-families/', 'U.S. Department of Defense (Military OneSource)', 'federal_agency', 'legal_aid_directory', array['military','lease_termination']::text[], 'tenant', 'html', 'Military OneSource page describing free military legal assistance, including lease and rental contract reviews, and how to find a legal assistance office.', null, '2026-07-28', 'unverifiable', '403 to WebFetch and browser-UA curl, and the militaryonesource.mil homepage also returns 403. No official page fetched today links to this exact URL (the DOJ SCRA pages do not), and no WebSearch budget was left. Existence and content NOT confirmed.', '2026-10-19T00:00:00Z', '{"notes":"militaryonesource.mil returns 403 to automated clients. Content was confirmed from an archive capture dated 2026-08-13 (article:modified_time 2026-07-28). The page links the AFLA locator and the DMDC SCRA website."}'::jsonb),
  ('6f83b116-d70f-5424-bc8f-17a478999249', 'US', 'federal', null, 'Avoid eviction | USAGov', 'https://www.usa.gov/avoid-eviction', 'U.S. Interagency Council on Homelessness', 'federal_agency', 'official_guide', array['eviction','rental_assistance']::text[], 'tenant', 'html', 'Federal step-by-step guide for renters at risk of eviction covering learning their rights, seeking local help and applying for rental assistance.', null, '2021-09-02', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Replaced outdated link | HUD''s TX and WY pages link it via the old URL usich.gov/tools-for-action/at-risk-of-eviction-help-is-available/, which redirects here. It is pandemic-era (2021) and references emergency rental assistance programs that have since ended, so label it as dated or consider omitting it."}'::jsonb),
  ('92004b5d-4a4b-5935-8ccc-db92dcad9eee', 'US', 'federal', null, 'Bed Bug Laws and Regulations', 'https://www.epa.gov/bedbugs/bed-bug-laws-and-regulations', 'U.S. Environmental Protection Agency', 'federal_agency', 'official_guide', array['lead_mold_pests']::text[], 'both', 'html', 'EPA page explaining that EPA regulates bed bug pesticides and noting that about 21 states have their own bed bug laws, mostly covering hotels and landlords.', null, '2026-01-06', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Useful cross-reference for state agents. EPA also has a local-help page at /bedbugs/local-resources-bed-bug-assistance (not opened)."}'::jsonb),
  ('bf8f1bae-8bc9-57ad-9e35-1655ead0a152', 'US', 'federal', null, 'Eviction and foreclosure (USAGov)', 'https://www.usa.gov/eviction-and-foreclosure', 'USAGov (General Services Administration)', 'federal_agency', 'official_guide', array['eviction','rental_assistance']::text[], 'tenant', 'html', 'USAGov page linking to federal guides on preventing or dealing with eviction or foreclosure.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The parent hub is usa.gov/housing-help (fetched, no date shown)."}'::jsonb),
  ('88db8968-a657-525b-a6de-9b558e66087b', 'US', 'federal', null, 'Financial and Housing Rights (Servicemembers and Veterans Initiative)', 'https://www.justice.gov/servicemembers/financial-and-housing-rights-0', 'U.S. Department of Justice, Civil Rights Division', 'federal_agency', 'official_guide', array['military','lease_termination','eviction']::text[], 'both', 'html', 'DOJ overview of Servicemembers Civil Relief Act protections, including residential lease termination rights and eviction protections.', null, '2025-05-12', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"servicemembers.gov redirects to justice.gov/servicemembers, which is the parent hub."}'::jsonb),
  ('b12fbffa-7066-58c9-8247-c715f4eb5f15', 'US', 'federal', null, 'Help for renters (CFPB)', 'https://www.consumerfinance.gov/housing/housing-insecurity/help-for-renters/', 'Consumer Financial Protection Bureau', 'federal_agency', 'official_guide', array['eviction','rental_assistance','tenant_screening','general']::text[], 'tenant', 'html', 'CFPB hub for renters covering rental assistance, avoiding eviction, tenant protections and tenant screening reports.', null, '2024-12-12', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The CFPB /renting/ URL returns 404, so this is the current renter hub. The parent page is /housing/housing-insecurity/ (last updated 2026-02-20)."}'::jsonb),
  ('16f6daa7-e40f-5e69-ba49-2219caddac15', 'US', 'federal', null, 'Help if You''ve Lost Housing (CFPB)', 'https://www.consumerfinance.gov/housing/housing-insecurity/lost-housing/', 'Consumer Financial Protection Bureau', 'federal_agency', 'official_guide', array['eviction','rental_assistance','military']::text[], 'tenant', 'html', 'CFPB page outlining resources after an eviction or foreclosure, including rental aid, subsidized housing lists, servicemember and veteran support and credit protection.', null, '2025-10-30', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('c1601f3f-d19e-5d34-b0f2-4cf2a292de71', 'US', 'federal', null, 'Helping Americans (HUD resources for renters and residents)', 'https://www.hud.gov/helping-americans', 'U.S. Department of Housing and Urban Development (HUD)', 'federal_agency', 'official_guide', array['general','rental_assistance','repairs_habitability','fair_housing','domestic_violence']::text[], 'tenant', 'html', 'HUD''s main public hub for renters, current HUD-assisted residents, voucher holders and others, with sections on reporting housing issues, current HUD residents, counseling and state resources.', null, null, 'unverifiable', 'Cloudflare 403 (''Attention Required! | Cloudflare'') to WebFetch and to browser-UA curl. Some evidence it exists: the header/footer of HUD''s own HUD Exchange site (hudexchange.info, fetched 2026-10-19) links to this exact URL. Page content and section list not verified. WebSearch budget for this session was used up, so no search confirmation.', '2026-10-19T00:00:00Z', '{"notes":"Replaces the pre-2025 renter/tenant-rights topic pages. Useful anchors: #CurrentResidents, #ReportIssue, #Counselor, #HousingChoiceVoucher. hud.gov returns a Cloudflare 403 to automated clients, so content was confirmed from an Internet Archive capture of this exact URL dated 2026-10-13."}'::jsonb),
  ('67839ab8-109e-533f-9d91-804e2b88afe0', 'US', 'federal', null, 'How to file a complaint against a landlord (USAGov)', 'https://www.usa.gov/tenant-rights', 'USAGov (General Services Administration)', 'federal_agency', 'official_guide', array['general','repairs_habitability','fair_housing']::text[], 'tenant', 'html', 'USAGov page on where tenants can turn about landlord disputes, including state tenant-rights offices, HUD for HUD-insured or managed housing, and legal aid.', null, '2026-04-15', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Its HUD links are legacy URLs (/topics/rental_assistance/tenantrights and /program_offices/housing/mfh/hc/complaint) that now redirect to /states and /contactus/multifamily-housing-complaint. /renters-rights, /landlord-tenant-issues, /rental-assistance and /housing-discrimination on usa.gov all return 404."}'::jsonb),
  ('194ef8af-9a70-511f-86af-519efaf7309d', 'US', 'federal', null, 'Know Your Rights: A Guide to the Servicemembers Civil Relief Act', 'https://www.justice.gov/servicemembers/know-your-rights-guide-servicemembers-civil-relief-act', 'U.S. Department of Justice', 'federal_agency', 'official_guide', array['military','lease_termination','eviction','security_deposit']::text[], 'both', 'html', 'DOJ guide summarizing SCRA protections for servicemembers and dependents, including terminating a residential lease after qualifying military orders.', null, '2025-05-14', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The statutory text is at 50 U.S.C. 3951 (evictions) and 3955 (lease termination). The DOJ SCRA summary page (/crt/servicemembers-civil-relief-act-summary, updated 2021-12-13) is less detailed."}'::jsonb),
  ('262fa7d8-11c8-58e7-b78d-cfaf190380dc', 'US', 'federal', null, 'Lead Safe Housing Rule (LSHR) Toolkit', 'https://www.hudexchange.info/programs/lead-based-paint/lshr-toolkit/introduction/', 'HUD Exchange (HUD)', 'federal_agency', 'official_guide', array['lead_mold_pests']::text[], 'landlord', 'html', 'HUD toolkit walking HUD-assisted housing providers and grantees through Lead Safe Housing Rule requirements by subpart and assistance type.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"EPA''s RRP page links this as HUD''s LSHR resource. WebFetch got a 404, but curl with a browser user-agent got HTTP 200 with the expected content."}'::jsonb),
  ('3a141414-8c33-55c4-adbd-718a5403d50d', 'US', 'federal', null, 'Lead-Based Paint Disclosure Rule (Section 1018 of Title X)', 'https://www.epa.gov/lead/lead-based-paint-disclosure-rule-section-1018-title-x', 'U.S. Environmental Protection Agency', 'federal_agency', 'official_guide', array['lead_mold_pests']::text[], 'landlord', 'html', 'EPA page describing the lead-based paint disclosure rule that applies to sellers, landlords, agents and property managers of most pre-1978 housing.', null, '2025-12-04', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"The regulation text is 24 CFR Part 35 Subpart A / 40 CFR Part 745 Subpart F."}'::jsonb),
  ('07c00c90-60b5-5bab-bc62-90a0693e42aa', 'US', 'federal', null, 'Rental Listing Scams', 'https://consumer.ftc.gov/articles/rental-listing-scams', 'Federal Trade Commission (Consumer Advice)', 'federal_agency', 'official_guide', array['general','security_deposit']::text[], 'tenant', 'html', 'FTC Consumer Advice article describing fake or hijacked rental listings used to collect application fees, deposits or personal information.', null, '2026-06', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('8921647b-93c4-5b75-ba3d-8e9c7123df3d', 'US', 'federal', null, 'Resident Rights & Responsibilities (HUD Multifamily brochure)', 'https://www.hud.gov/sites/dfiles/Housing/documents/resident_rights_brochure_8.pdf', 'HUD Office of Multifamily Housing Programs', 'federal_agency', 'official_guide', array['repairs_habitability','entry_privacy','eviction','retaliation','general']::text[], 'both', 'pdf', 'HUD brochure describing the rights and responsibilities of residents in HUD-assisted multifamily housing programs.', null, '2018-03', 'unverifiable', 'Cloudflare 403 to WebFetch and curl. Existence and content of the PDF NOT confirmed.', '2026-10-19T00:00:00Z', '{"notes":"The PDF was retrieved from an Internet Archive capture of this exact URL (2026-10-10). The opening text reads ''RESIDENT RIGHTS & RESPONSIBILITIES ... This brochure applies to assisted housing programs administered by HUD''. The PDF metadata modification date is 2018-03-05."}'::jsonb),
  ('0a5c39c3-a97d-5829-b928-cc6b0c2b52c5', 'US', 'federal', null, 'Review your rental background check (CFPB)', 'https://www.consumerfinance.gov/rules-policy/tenant-background-checks/review-your-rental-background-check/', 'Consumer Financial Protection Bureau', 'federal_agency', 'official_guide', array['tenant_screening']::text[], 'tenant', 'html', 'CFPB guide on checking a rental background (tenant screening) report for errors such as wrong eviction or criminal records and how to dispute them.', null, '2023-10-11', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Page modified 2024-01-30. Some related CFPB tenant-screening news and blog items have been moved under /archive/."}'::jsonb)
insert into property.legal_resources (id, jurisdiction_code, scope, locality, title, url, publisher, publisher_type, category, topics, audience, format, description, citation, source_updated, verification, verification_note, checked_at, metadata) values
  ('c4617a2c-a083-5bd2-a57c-b113cbf45605', 'US', 'federal', null, 'Sample Lessor''s Disclosure of Information on Lead-Based Paint (English)', 'https://www.epa.gov/sites/default/files/documents/lesr_eng.pdf', 'U.S. Environmental Protection Agency', 'federal_agency', 'official_guide', array['lead_mold_pests']::text[], 'landlord', 'pdf', 'EPA sample lease disclosure form for lead-based paint and lead-based paint hazards in pre-1978 housing.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Linked from EPA''s real-estate-disclosure page (confirmed). The URL returned HTTP 200 application/pdf, but the PDF content was not read. A Spanish version is at /sites/default/files/documents/spanless.pdf."}'::jsonb),
  ('fb0a5c9d-d788-5377-b56c-353d818b26d4', 'US', 'federal', null, 'Tenant Background Checks and Your Rights', 'https://consumer.ftc.gov/articles/tenant-background-checks-and-your-rights', 'Federal Trade Commission (Consumer Advice)', 'federal_agency', 'official_guide', array['tenant_screening']::text[], 'tenant', 'html', 'FTC Consumer Advice article on how tenant screening reports are used and renters'' rights under the Fair Credit Reporting Act.', null, '2025-08', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('b3f15519-41da-56e8-b58d-05a27cfa4dd1', 'US', 'federal', null, 'Using Consumer Reports: What Landlords Need to Know', 'https://www.ftc.gov/business-guidance/resources/using-consumer-reports-what-landlords-need-know', 'Federal Trade Commission', 'federal_agency', 'official_guide', array['tenant_screening']::text[], 'landlord', 'html', 'FTC business guidance on Fair Credit Reporting Act obligations for landlords and property managers who use credit, rental-history or criminal background reports.', null, '2023-07', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('637822b1-a23a-510e-b876-ec62f45d9336', 'US', 'federal', null, 'Violence Against Women Act (VAWA) - HUD', 'https://www.hud.gov/vawa', 'U.S. Department of Housing and Urban Development (HUD)', 'federal_agency', 'official_guide', array['domestic_violence','lease_termination','eviction']::text[], 'both', 'html', 'HUD page on VAWA housing protections for survivors of domestic violence, dating violence, sexual assault and stalking in HUD-covered housing, with FAQs, forms and notices.', null, null, 'unverifiable', 'Cloudflare 403. This short URL''s existence and target are NOT confirmed.', '2026-10-19T00:00:00Z', '{"notes":"The URL canonicalizes to /VAWA. The page links the Notice of Occupancy Rights form HUD-5380 (hud.gov/sites/dfiles/OCHCO/documents/5380.pdf, not opened) and the September 2024 interagency VAWA housing statement. Confirmed from an archive capture dated 2026-10-06."}'::jsonb),
  ('71dd616f-b4d6-585e-89d4-3cdd90d717f1', 'US', 'federal', null, 'What is a tenant screening report? (CFPB)', 'https://www.consumerfinance.gov/ask-cfpb/what-is-a-tenant-screening-report-en-2102/', 'Consumer Financial Protection Bureau', 'federal_agency', 'official_guide', array['tenant_screening']::text[], 'both', 'html', 'CFPB Q&A explaining what tenant screening reports contain and how landlords use them in rental decisions.', null, '2021-07-01', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Last reviewed 2021-07-01, so it is older content."}'::jsonb),
  ('c4a5fe58-2a42-510d-a63f-ab6c2e0bee0b', 'US', 'federal', null, 'What should I do if my rental application is denied because of a tenant screening report? (CFPB)', 'https://www.consumerfinance.gov/ask-cfpb/what-should-i-do-if-my-rental-application-is-denied-because-of-a-tenant-screening-report-en-2105/', 'Consumer Financial Protection Bureau', 'federal_agency', 'official_guide', array['tenant_screening']::text[], 'tenant', 'html', 'CFPB Q&A on adverse-action notices, free report copies and disputes when a rental application is denied based on a screening report.', null, '2025-10-30', 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Last reviewed 2024-05-28 and modified 2025-10-30."}'::jsonb),
  ('7d35cc5e-ba40-56b0-8303-53d67177756d', 'US', 'federal', null, 'What to do if you''re facing eviction (CFPB)', 'https://www.consumerfinance.gov/housing/housing-insecurity/help-for-renters/what-to-do-if-youre-facing-eviction/', 'Consumer Financial Protection Bureau', 'federal_agency', 'official_guide', array['eviction','rental_assistance']::text[], 'tenant', 'html', 'CFPB guide describing options for renters behind on rent, including assistance programs, repayment conversations, responding to an eviction case and finding legal help.', null, '2024-12-12', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('dcd33d63-e3d4-5120-aae4-2b62563b4c55', 'US', 'federal', null, 'Your tenant and debt collection rights (CFPB)', 'https://www.consumerfinance.gov/housing/housing-insecurity/help-for-renters/your-tenant-debt-collection-rights/', 'Consumer Financial Protection Bureau', 'federal_agency', 'official_guide', array['eviction','general','fair_housing']::text[], 'tenant', 'html', 'CFPB page describing federal, state and local renter protections, including debt collection rules for back rent, eviction protections and where to report problems.', null, '2026-02-20', 'verified', null, '2026-10-19T00:00:00Z', '{}'::jsonb),
  ('4d1cddfb-68f2-5719-b6fe-a8693ccfff37', 'US', 'federal', null, 'Find a Housing Counselor (CFPB)', 'https://www.consumerfinance.gov/find-a-housing-counselor/', 'Consumer Financial Protection Bureau', 'federal_agency', 'other', array['rental_assistance','eviction']::text[], 'tenant', 'html', 'CFPB ZIP-code search tool for nearby HUD-approved housing counseling agencies, powered by HUD''s official list.', null, null, 'verified', null, '2026-10-19T00:00:00Z', '{"notes":"Server-rendered alternative to the HUD Salesforce finder. Curl received a 403, but WebFetch succeeded."}'::jsonb),
