  ('5f808b52-97bf-51e7-87d2-46e4cecf4a82', 'WI', 'state', null, 'Wis. Admin. Code ATCP 134.06 - Security deposits', 'https://docs.legis.wisconsin.gov/document/administrativecode/ATCP%20134.06', 'Wisconsin State Legislature (DATCP rule)', 'state_legislature', 'statute', array['security_deposit']::text[], 'both', 'html', 'Rule section on check-in sheets, the 21-day return deadline and itemized deductions for security deposits.', 'Wis. Admin. Code ATCP 134.06', null, 'unverifiable', 'Host unreachable. The 03/2026 DATCP guide confirms ATCP 134.06 is the security-deposit section: check-in (134.06(1)), return (134.06(2)), deductions (134.06(3)). DATCP''s tenant fact sheet confirms the 21-day return and the 7-day check-in sheet.', '2026-10-19T00:00:00Z', '{"notes":"Withholding grounds are in Wis. Stat. 704.28. URL linked from WisLawHelp pages. Official site unreachable this session."}'::jsonb),
