  ('801a2c3f-0021-5dd2-b09b-c0a5b259935d', 'WV', 'state', null, 'W. Va. Code 37-6-30 - Duties of landlord (fit and habitable condition)', 'https://code.wvlegislature.gov/37-6-30/', 'West Virginia Legislature', 'state_legislature', 'statute', array['repairs_habitability']::text[], 'both', 'html', 'Statute section setting a landlord''s duty to deliver and maintain rental premises in a fit and habitable condition.', 'W. Va. Code 37-6-30', null, 'unverifiable', 'Returns HTTP 403 to automated clients. A web search (done before the budget ran out) indexes this exact URL as W. Va. Code 37-6-30, the landlord''s duty to deliver and keep the unit fit and habitable. Legal Aid WV''s ''What To Do When Housing Conditions Are Bad'' article links to this same URL and cites the same section.', '2026-10-19T00:00:00Z', '{"notes":"Official site blocks automated fetching (403). URL is linked from Legal Aid WV''s ''What To Do When Housing Conditions Are Bad'' page, which cites 37-6-30. Legal Aid WV states WV statute does not provide repair-and-deduct unless the lease allows it."}'::jsonb),
  ('8b1300d7-09b2-5fb1-a809-848f20a08363', 'WV', 'state', null, 'W. Va. Code 37-6-5 - Notice to terminate periodic tenancies', 'https://code.wvlegislature.gov/37-6-5/', 'West Virginia Legislature', 'state_legislature', 'statute', array['lease_termination','rent_increase']::text[], 'both', 'html', 'Statute section on the written notice required to end a month-to-month or other periodic tenancy.', 'W. Va. Code 37-6-5', null, 'unverifiable', 'Returns HTTP 403 to automated clients. Legal Aid WV''s ''How Much Notice is Required in a Month-to-Month Tenancy?'' links to this exact URL as WV Code 37-6-5 (one full rent period of written notice to end a periodic tenancy). Tagging issue: Legal Aid WV says the section covers only ending a periodic tenancy, not rent increases, so the ''rent_increase'' topic is not supported. Recommend dropping it.', '2026-10-19T00:00:00Z', '{"notes":"Official site blocks automated fetching (403). URL linked from Legal Aid WV''s month-to-month notice page. No separate WV rent-increase notice statute was identified; tagged rent_increase because periodic-tenancy terms change through this notice period."}'::jsonb),
  ('e4f78c06-65a1-5cab-837d-16bb14ef1d07', 'WV', 'state', null, 'W. Va. Code 37-6-6 - Personal property left in rental housing', 'https://code.wvlegislature.gov/37-6-6/', 'West Virginia Legislature', 'state_legislature', 'statute', array['eviction','lease_termination']::text[], 'both', 'html', 'Statute section on notice, storage and disposal of a tenant''s personal property left after a tenancy ends.', 'W. Va. Code 37-6-6', null, 'unverifiable', 'Returns HTTP 403 to automated clients. Legal Aid WV''s ''Abandoned Personal Property in Rental Housing'' links to this exact URL as the statute on notice, storage and disposal of property left behind (30 days from mailing, 60 for active military). Matches the claimed content. Post-eviction property is handled separately, so the ''eviction'' tag is only loosely supported.', '2026-10-19T00:00:00Z', '{"notes":"Official site blocks automated fetching (403). URL and subject taken from Legal Aid WV''s ''Abandoned Personal Property in Rental Housing'' page."}'::jsonb),
